import json
D=json.load(open('/workspace/contracts/openapi.contract.json'))
for path, ms in D['paths'].items():
 for method,op in ms.items():
  if method not in {'get','post','put','patch','delete'}: continue
  print('\n'+'='*100)
  print(method.upper(),path,op.get('operationId'))
  print('security',op.get('security'))
  for p in op.get('parameters',[]): print('PARAM',json.dumps(p))
  rb=op.get('requestBody')
  if rb: print('REQUEST',json.dumps(rb,separators=(',',':')))
  print('RESPONSES')
  for code,r in op.get('responses',{}).items(): print(code,json.dumps(r,separators=(',',':')))
