package main

import (
	"encoding/json"
	"io"
	"log"
	"mime"
	"net/http"
	"os"
	"path/filepath"
	"runtime/debug"
	"strings"
)

type handlerFunc func(http.ResponseWriter,*http.Request,*Actor,bsonMap) (any,int,*apiError)
type bsonMap map[string]any

type route struct { operation string; method string; handler handlerFunc }

func (a *App) routes() map[string]route {
	return map[string]route{
		"/api/authenticate-user":{"authenticate_user","POST",a.handleLogin},
		"/api/select-active-role":{"select_active_role","POST",a.handleSelectRole},
		"/api/create-user":{"create_user","POST",a.handleCreateUser},
		"/api/update-user-access":{"update_user_access","POST",a.handleUpdateUser},
		"/api/create-sample-type":{"create_sample_type","POST",a.handleCreateSampleType},
		"/api/update-sample-type":{"update_sample_type","POST",a.handleUpdateSampleType},
		"/api/create-location":{"create_location","POST",a.handleCreateLocation},
		"/api/update-location":{"update_location","POST",a.handleUpdateLocation},
		"/api/set-location-status":{"set_location_status","POST",a.handleLocationStatus},
		"/api/set-location-function-status":{"set_location_function_status","POST",a.handleFunctionStatus},
		"/api/create-connection":{"create_connection","POST",a.handleCreateConnection},
		"/api/set-connection-status":{"set_connection_status","POST",a.handleConnectionStatus},
		"/api/configure-capacity":{"configure_capacity","POST",a.handleCapacity},
		"/api/configure-laboratory-acceptance":{"configure_laboratory_acceptance","POST",a.handleLabAcceptance},
		"/api/set-worker-availability":{"set_worker_availability","POST",a.handleWorkerAvailability},
		"/api/check-serviceability":{"check_serviceability","POST",a.handleCheckServiceability},
		"/api/create-collection-request":{"create_collection_request","POST",a.handleCreateRequest},
		"/api/ingest-presealed-sample":{"ingest_presealed_sample","POST",a.handlePresealed},
		"/api/accept-assignment":{"accept_assignment","POST",a.handleAcceptAssignment},
		"/api/decline-assignment":{"decline_assignment","POST",a.handleDeclineAssignment},
		"/api/collect-and-seal-sample":{"collect_and_seal_sample","POST",a.handleCollectSeal},
		"/api/update-assignment-progress":{"update_assignment_progress","POST",a.handleProgress},
		"/api/record-worker-location":{"record_worker_location","POST",a.handleWorkerLocation},
		"/api/initiate-handoff":{"initiate_handoff","POST",a.handleInitiateHandoff},
		"/api/confirm-handoff":{"confirm_handoff","POST",a.handleConfirmHandoff},
		"/api/record-handling-checkpoint":{"record_handling_checkpoint","POST",a.handleCheckpoint},
		"/api/confirm-laboratory-receipt":{"confirm_laboratory_receipt","POST",a.handleLabReceipt},
		"/api/record-laboratory-exception":{"record_laboratory_exception","POST",a.handleLabException},
		"/api/cancel-journey":{"cancel_journey","POST",a.handleCancelJourney},
		"/api/edit-active-plan":{"edit_active_plan","POST",a.handleEditPlan},
		"/api/merge-journeys":{"merge_journeys","POST",a.handleMergeJourneys},
		"/api/split-journey":{"split_journey","POST",a.handleSplitJourney},
		"/api/reroute-journey":{"reroute_journey","POST",a.handleReroute},
		"/api/report-disruption":{"report_disruption","POST",a.handleDisruption},
		"/api/list-role-work":{"list_role_work","POST",a.handleRoleWork},
		"/api/read-journey-plan":{"read_journey_plan","POST",a.handleReadJourney},
		"/api/read-operations-state":{"read_operations_state","POST",a.handleOperations},
		"/api/read-sample-lifecycle":{"read_sample_lifecycle","POST",a.handleLifecycle},
		"/api/read-serviceability-snapshot":{"read_serviceability_snapshot","POST",a.handleSnapshot},
		"/api/search-audit-trail":{"search_audit_trail","POST",a.handleAuditSearch},
	}
}

func (a *App) ServeHTTP(w http.ResponseWriter,r *http.Request) {
	defer func(){if x:=recover();x!=nil{log.Printf("panic: %v\n%s",x,debug.Stack());writeError(w,fail(500,"internal_error","Internal server error"))}}()
	w.Header().Set("X-Content-Type-Options","nosniff")
	w.Header().Set("Referrer-Policy","same-origin")
	if r.URL.Path=="/ready" { if r.Method!="GET"{writeError(w,fail(405,"method_not_allowed","Method not allowed"));return};if a.client.Ping(r.Context(),nil)!=nil{writeJSON(w,503,map[string]any{"status":"starting"});return};writeJSON(w,200,map[string]any{"status":"ready"});return }
	if r.URL.Path=="/maps/bangalore.pmtiles" { http.ServeFile(w,r,"/opt/arena/map-assets/bangalore.pmtiles");return }
	if r.URL.Path=="/api/events" { a.handleEvents(w,r);return }
	if r.URL.Path=="/api/ui/bootstrap" { a.handleBootstrapHTTP(w,r);return }
	if strings.HasPrefix(r.URL.Path,"/api/read-sample-state/") { a.handleSampleStateHTTP(w,r,strings.TrimPrefix(r.URL.Path,"/api/read-sample-state/"));return }
	if strings.HasPrefix(r.URL.Path,"/api/read-user/") { a.handleReadUserHTTP(w,r,strings.TrimPrefix(r.URL.Path,"/api/read-user/"));return }
	if rt,ok:=a.routes()[r.URL.Path];ok { a.execute(w,r,rt);return }
	if strings.HasPrefix(r.URL.Path,"/api/"){writeError(w,fail(404,"not_found","Operation not found"));return}
	a.serveFrontend(w,r)
}

func (a *App) execute(w http.ResponseWriter,r *http.Request,rt route) {
	if r.Method!=rt.method { writeError(w,fail(405,"method_not_allowed","Method not allowed"));return }
	body,e:=decodeBody(r);if e!=nil{writeError(w,e);return}
	if e=validateContractBody(rt.operation,body);e!=nil{writeError(w,e);return}
	var actor *Actor
	if rt.operation!="authenticate_user" { actor,e=a.authenticate(r);if e!=nil{writeError(w,e);return};if e=a.authorize(actor,rt.operation);e!=nil{a.audit(r.Context(),actor,"permission_check",rt.operation,"",false,map[string]any{"code":e.Code});writeError(w,e);return} }
	data,status,e:=rt.handler(w,r,actor,body);if e!=nil{if actor!=nil{a.audit(r.Context(),actor,rt.operation,"operation","",false,map[string]any{"code":e.Code})};writeError(w,e);return}
	writeJSON(w,status,map[string]any{"data":data})
}

func decodeBody(r *http.Request) (bsonMap,*apiError) {
	defer r.Body.Close();d:=json.NewDecoder(io.LimitReader(r.Body,1<<20));d.UseNumber();var body bsonMap
	if err:=d.Decode(&body);err!=nil{return nil,fail(400,"invalid_json","Request body must be valid JSON")};if body==nil{return nil,fail(400,"invalid_json","Request body must be an object")}
	if d.Decode(&struct{}{})!=io.EOF{return nil,fail(400,"invalid_json","Request body must contain one JSON value")};return body,nil
}

var operationSchemas map[string]struct{Allowed,Required map[string]bool}
func loadContractSchemas() {
	operationSchemas=map[string]struct{Allowed,Required map[string]bool}{}
	b,e:=os.ReadFile("/workspace/app-setup/openapi.json");if e!=nil{return};var d map[string]any;if json.Unmarshal(b,&d)!=nil{return}
	paths,_:=d["paths"].(map[string]any);for _,pv:=range paths{methods,_:=pv.(map[string]any);for _,ov:=range methods{op,_:=ov.(map[string]any);id,_:=op["operationId"].(string);if id==""{continue};allowed,required:=map[string]bool{},map[string]bool{};rb,_:=op["requestBody"].(map[string]any);content,_:=rb["content"].(map[string]any);app,_:=content["application/json"].(map[string]any);schema,_:=app["schema"].(map[string]any);props,_:=schema["properties"].(map[string]any);for k:=range props{allowed[k]=true};if req,ok:=schema["required"].([]any);ok{for _,x:=range req{required[x.(string)]=true}};operationSchemas[id]=struct{Allowed,Required map[string]bool}{allowed,required}}}
}
func validateContractBody(operation string,body bsonMap)*apiError{if operationSchemas==nil{loadContractSchemas()};s,ok:=operationSchemas[operation];if !ok{return nil};for k:=range body{if !s.Allowed[k]{return fail(400,"invalid_json","Unexpected field: "+k)}};for k:=range s.Required{if _,ok:=body[k];!ok{return fail(400,"invalid_json","Missing required field: "+k)}};return nil}

func writeJSON(w http.ResponseWriter,status int,v any){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);_ = json.NewEncoder(w).Encode(v)}
func writeError(w http.ResponseWriter,e *apiError){writeJSON(w,e.Status,map[string]any{"error":e.Message,"code":e.Code})}

func (a *App) serveFrontend(w http.ResponseWriter,r *http.Request){
	if r.Method!="GET"&&r.Method!="HEAD"{writeError(w,fail(405,"method_not_allowed","Method not allowed"));return}
	path:=filepath.Join(a.webDir,filepath.Clean("/"+r.URL.Path));if info,e:=os.Stat(path);e==nil&&!info.IsDir(){if t:=mime.TypeByExtension(filepath.Ext(path));t!=""{w.Header().Set("Content-Type",t)};http.ServeFile(w,r,path);return};http.ServeFile(w,r,filepath.Join(a.webDir,"index.html"))
}

