func (a *App) handleLogin(_ http.ResponseWriter,r *http.Request,_ *Actor,body bsonMap)(any,int,*apiError){
	username,password:=asString(body["username"]),asString(body["password"]);var u bson.M
	if a.db.Collection("users").FindOne(r.Context(),bson.M{"usernameLower":strings.ToLower(username),"active":true}).Decode(&u)!=nil||asString(u["passwordHash"])!=passwordHash(username,password){a.audit(r.Context(),nil,"sign_in","user",username,false,bson.M{"reason":"invalid_credentials"});return nil,0,fail(401,"invalid_credentials","Invalid username or password")}
	roles:=stringSlice(u["roles"]);active:="";if len(roles)==1{active=roles[0]};t:=token();_,e:=a.db.Collection("sessions").InsertOne(r.Context(),bson.M{"token":t,"userId":asString(u["userId"]),"activeRole":active,"createdAt":now(),"expiresAt":time.Now().UTC().Add(24*time.Hour).Format(time.RFC3339Nano)});if e!=nil{return nil,0,fail(500,"internal_error","Could not create session")}
	actor:=&Actor{UserID:asString(u["userId"]),Roles:roles,ActiveRole:active};a.audit(r.Context(),actor,"sign_in","user",actor.UserID,true,bson.M{})
	return bson.M{"sessionToken":t,"userId":actor.UserID,"roles":roles,"activeRole":active},200,nil
}

func (a *App) handleSelectRole(_ http.ResponseWriter,r *http.Request,actor *Actor,body bsonMap)(any,int,*apiError){
	role:=asString(body["role"]);if !validRoles[role]||!contains(actor.Roles,role){return nil,0,fail(403,"forbidden","Role is not assigned to this user")}
	_,e:=a.db.Collection("sessions").UpdateOne(r.Context(),bson.M{"token":actor.SessionToken},bson.M{"$set":bson.M{"activeRole":role}});if e!=nil{return nil,0,fail(500,"internal_error","Could not select role")};actor.ActiveRole=role;a.audit(r.Context(),actor,"select_active_role","session",actor.UserID,true,bson.M{"role":role})
	return bson.M{"activeRole":role,"roles":actor.Roles},200,nil
}

func (a *App) handleCreateUser(_ http.ResponseWriter,r *http.Request,actor *Actor,body bsonMap)(any,int,*apiError){
	roles:=stringsFromAny(body["roles"]);for _,role:=range roles{if !validRoles[role]{return nil,0,fail(400,"invalid_json","Unknown role")}}
	if (contains(roles,"node_handler")||contains(roles,"laboratory_team"))&&asString(body["assignedLocationId"])==""{return nil,0,fail(400,"invalid_assignment","Assigned location is required")}
	u:=bson.M{"userId":uuid(),"username":asString(body["username"]),"usernameLower":strings.ToLower(asString(body["username"])),"passwordHash":passwordHash(asString(body["username"]),asString(body["initialPassword"])),"email":asString(body["email"]),"fullName":asString(body["fullName"]),"phone":asString(body["phone"]),"roles":roles,"qualifications":stringsFromAny(body["qualifications"]),"certifications":normalCertifications(body["certifications"]),"active":asBool(body["active"]),"available":true,"capacityUnits":1,"assignmentCount":0,"assignedLocationId":asString(body["assignedLocationId"]),"createdAt":now()}
	_,e:=a.db.Collection("users").InsertOne(r.Context(),u);if mongo.IsDuplicateKeyError(e){return nil,0,fail(409,"duplicate_username","Username already exists")};if e!=nil{return nil,0,fail(500,"internal_error","Could not create user")};a.audit(r.Context(),actor,"create_user","user",asString(u["userId"]),true,bson.M{"roles":roles});return publicUser(u),201,nil
}

func (a *App) handleUpdateUser(_ http.ResponseWriter,r *http.Request,actor *Actor,body bsonMap)(any,int,*apiError){
	id:=asString(body["userId"]);roles:=stringsFromAny(body["roles"]);for _,role:=range roles{if !validRoles[role]{return nil,0,fail(400,"invalid_json","Unknown role")}}
	set:=bson.M{"roles":roles,"active":asBool(body["active"])};if _,ok:=body["qualifications"];ok{set["qualifications"]=stringsFromAny(body["qualifications"])};if _,ok:=body["certifications"];ok{set["certifications"]=normalCertifications(body["certifications"])};if _,ok:=body["assignedLocationId"];ok{set["assignedLocationId"]=asString(body["assignedLocationId"])}
