}

func normalCertifications(v any) bson.A { out:=bson.A{};switch a:=v.(type){case []any:for _,x:=range a{m:=toBson(x);if asString(m["code"])!=""{if _,ok:=m["active"];!ok{m["active"]=true};out=append(out,m)}};case bson.A:for _,x:=range a{out=append(out,toBson(x))}};return out }
func stringsFromAny(v any)[]string{out:=[]string{};if a,ok:=v.([]any);ok{for _,x:=range a{out=append(out,asString(x))}};if a,ok:=v.(bson.A);ok{for _,x:=range a{out=append(out,asString(x))}};return out}
func toBson(v any)bson.M{switch x:=v.(type){case bson.M:return x;case map[string]any:return bson.M(x);case bsonMap:return bson.M(x)};return bson.M{}}

func (a *App) handleCreateSampleType(_ http.ResponseWriter,r *http.Request,actor *Actor,body bsonMap)(any,int,*apiError){
	if asFloat(body["temperatureMinC"])>asFloat(body["temperatureMaxC"]){return nil,0,fail(400,"invalid_handling_rule","Minimum temperature exceeds maximum")}
