func (a *App) activeJourney(ctx context.Context,id string,expected int)(bson.M,*apiError){var j bson.M;if a.db.Collection("journeys").FindOne(ctx,bson.M{"journeyId":id}).Decode(&j)!=nil{return nil,fail(404,"not_found","Journey not found")};if asInt(j["planVersion"])!=expected{return nil,fail(409,"stale_plan","Journey plan version has changed")};if asString(j["status"])!="active"{return nil,fail(409,"inactive_plan","Journey plan is not active")};return j,nil}
