func (a *App) handleEditPlan(_ http.ResponseWriter,r *http.Request,actor *Actor,body bsonMap)(any,int,*apiError){if old,ok,e:=a.idempotent(r.Context(),actor,"edit_active_plan",bson.M(body));e!=nil{return nil,0,e}else if ok{return old,201,nil};a.mu.Lock();defer a.mu.Unlock();j,e:=a.activeJourney(r.Context(),asString(body["journeyId"]),asInt(body["expectedPlanVersion"]));if e!=nil{return nil,0,e};change:=asString(body["changeType"]);changes:=toBson(body["changes"]);if a.hasCompletedWork(r.Context(),asString(j["journeyId"]))&&(change=="remove_stop"||change=="reorder_stops"||change=="replace_route"||change=="reroute"){return nil,0,fail(409,"completed_work_immutable","Completed work cannot be changed")};set:=bson.M{"planVersion":asInt(j["planVersion"])+1};switch change{case "reorder_stops","replace_route","reroute":if stops,ok:=changes["orderedStops"];ok{set["orderedStops"]=stops};case "replace_worker","reassign_worker":assignmentID,workerID:=asString(changes["assignmentId"]),asString(changes["workerId"]);var x bson.M;if a.db.Collection("assignments").FindOne(r.Context(),bson.M{"assignmentId":assignmentID,"journeyId":j["journeyId"]}).Decode(&x)!=nil{return nil,0,fail(409,"invalid_assignment","Assignment is not part of this journey")};if asString(x["status"])=="completed"{return nil,0,fail(409,"completed_work_immutable","Completed assignment cannot be reassigned")};var u bson.M;if a.db.Collection("users").FindOne(r.Context(),bson.M{"userId":workerID,"roles":x["requiredRole"],"active":true,"available":true}).Decode(&u)!=nil{return nil,0,fail(409,"ineligible_worker","Replacement worker is ineligible")};_,_=a.db.Collection("assignments").UpdateOne(r.Context(),bson.M{"assignmentId":assignmentID},bson.M{"$set":bson.M{"workerId":workerID,"status":"offered","offerExpiresAt":time.Now().UTC().Add(15*time.Minute).Format(time.RFC3339Nano)}});case "cancel_work":assignmentID:=asString(changes["assignmentId"]);var x bson.M;if a.db.Collection("assignments").FindOne(r.Context(),bson.M{"assignmentId":assignmentID,"journeyId":j["journeyId"]}).Decode(&x)!=nil{return nil,0,fail(409,"invalid_assignment","Assignment not found")};if asString(x["status"])=="completed"{return nil,0,fail(409,"completed_work_immutable","Completed assignment cannot be cancelled")};_,_=a.db.Collection("assignments").UpdateOne(r.Context(),bson.M{"assignmentId":assignmentID},bson.M{"$set":bson.M{"status":"cancelled","active":false}})};res,_:=a.db.Collection("journeys").UpdateOne(r.Context(),bson.M{"journeyId":j["journeyId"],"planVersion":j["planVersion"],"status":"active"},bson.M{"$set":set});if res.ModifiedCount==0{return nil,0,fail(409,"concurrent_conflict","Journey changed concurrently")};_=a.db.Collection("journeys").FindOne(r.Context(),bson.M{"journeyId":j["journeyId"]}).Decode(&j);out:=journeyDTO(j);a.saveIdempotent(r.Context(),actor,"edit_active_plan",bson.M(body),out);a.audit(r.Context(),actor,"edit_active_plan","journey",asString(j["journeyId"]),true,bson.M{"changeType":change});return out,201,nil}

