func (a *App) handleLogin(_ http.ResponseWriter,r *http.Request,_ *Actor,body bsonMap)(any,int,*apiError){
	username,password:=asString(body["username"]),asString(body["password"]);var u bson.M
	if a.db.Collection("users").FindOne(r.Context(),bson.M{"usernameLower":strings.ToLower(username),"active":true}).Decode(&u)!=nil||asString(u["passwordHash"])!=passwordHash(username,password){a.audit(r.Context(),nil,"sign_in","user",username,false,bson.M{"reason":"invalid_credentials"});return nil,0,fail(401,"invalid_credentials","Invalid username or password")}
	roles:=stringSlice(u["roles"]);active:="";if len(roles)==1{active=roles[0]};t:=token();_,e:=a.db.Collection("sessions").InsertOne(r.Context(),bson.M{"token":t,"userId":asString(u["userId"]),"activeRole":active,"createdAt":now(),"expiresAt":time.Now().UTC().Add(24*time.Hour).Format(time.RFC3339Nano)});if e!=nil{return nil,0,fail(500,"internal_error","Could not create session")}
	actor:=&Actor{UserID:asString(u["userId"]),Roles:roles,ActiveRole:active};a.audit(r.Context(),actor,"sign_in","user",actor.UserID,true,bson.M{})
	return bson.M{"sessionToken":t,"userId":actor.UserID,"roles":roles,"activeRole":active},200,nil
