		}
		if _, ok := m["active"]; !ok {
			m["active"] = true
		}
		out = append(out, m)
	}
	return out
}

func stringsFromAny(v any) []string {
	out := []string{}
	switch a := v.(type) {
	case []any:
		for _, x := range a { out = append(out, asString(x)) }
	case bson.A:
		for _, x := range a { out = append(out, asString(x)) }
	case []string:
		return a
	}
	return out
}

