func (a *App) handleDeclineAssignment(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	if old, ok, e := a.idempotent(r.Context(), actor, "decline_assignment", bson.M(body)); e != nil {
		return nil, 0, e
	} else if ok {
		return old, 201, nil
	}
	id := asString(body["assignmentId"])
	var x bson.M
	if a.db.Collection("assignments").FindOne(r.Context(), bson.M{"assignmentId": id}).Decode(&x) != nil {
		return nil, 0, fail(404, "not_found", "Assignment not found")
	}
	if asString(x["workerId"]) != actor.UserID {
		return nil, 0, fail(409, "offer_not_offered", "Assignment was not offered to this worker")
	}
	declined := stringSlice(x["declinedBy"])
	declined = append(declined, actor.UserID)
	var st bson.M
	_ = a.db.Collection("samples").FindOne(r.Context(), bson.M{"sampleId": x["sampleId"]}).Decode(&st)
	var typ bson.M
	_ = a.db.Collection("sample_types").FindOne(r.Context(), bson.M{"sampleTypeId": st["sampleTypeId"]}).Decode(&typ)
	next := a.selectWorker(r, asString(x["requiredRole"]), asString(x["nodeId"]), typ, declined)
	status := "unassigned"
	if next != "" {
		status = "offered"
	}
	when := now()
	if v := asString(body["declinedAt"]); v != "" {
		when = v
	}
	entry := timelineEntry(actor, "assignment_declined", "assignment", id, bson.M{"reason": asString(body["reason"])})
	_, _ = a.db.Collection("assignments").UpdateOne(r.Context(), bson.M{"assignmentId": id}, bson.M{"$set": bson.M{"status": status, "workerId": next, "declinedBy": declined, "offerExpiresAt": time.Now().UTC().Add(15 * time.Minute).Format(time.RFC3339Nano)}, "$push": bson.M{"history": entry}})
	_, _ = a.db.Collection("users").UpdateOne(r.Context(), bson.M{"userId": actor.UserID}, bson.M{"$inc": bson.M{"declinePenalty": 1}})
	out := bson.M{"assignmentId": id, "status": "pending", "declinedBy": actor.UserID, "declinedAt": when}
	if next != "" {
		out["reofferedTo"] = next
	}
	a.saveIdempotent(r.Context(), actor, "decline_assignment", bson.M(body), out)
	a.audit(r.Context(), actor, "decline_assignment", "assignment", id, true, out)
	return out, 201, nil
}

