func (a *App) handleConfirmHandoff(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	if old, ok, e := a.idempotent(r.Context(), actor, "confirm_handoff", bson.M(body)); e != nil {
		return nil, 0, e
	} else if ok {
		return old, 201, nil
	}
	id := asString(body["handoffId"])
	var h bson.M
	if a.db.Collection("handoffs").FindOne(r.Context(), bson.M{"handoffId": id}).Decode(&h) != nil {
		return nil, 0, fail(404, "not_found", "Handoff not found")
	}
	side := asString(body["confirmationSide"])
	expected := asString(h[side+"Id"])
	if expected == "" {
		if side == "sender" {
			expected = asString(h["senderId"])
		} else {
			expected = asString(h["receiverId"])
		}
	}
	if expected != actor.UserID {
		return nil, 0, fail(403, "forbidden", "Only the named party can confirm this side")
	}
	sender := asBool(h["senderConfirmed"])
	receiver := asBool(h["receiverConfirmed"])
	if side == "sender" {
		sender = true
	} else {
		receiver = true
	}
	status := "pending"
	holder := asString(h["senderId"])
	set := bson.M{side + "Confirmed": true}
	if sender && receiver {
		status = "confirmed"
		holder = asString(h["receiverId"])
		set["status"] = status
		set["completedAt"] = asString(body["confirmedAt"])
		_, _ = a.db.Collection("samples").UpdateOne(r.Context(), bson.M{"sampleId": h["sampleId"], "currentHolderId": h["senderId"]}, bson.M{"$set": bson.M{"currentHolderId": holder}, "$unset": bson.M{"pendingHandoffId": ""}})
	}
	_, _ = a.db.Collection("handoffs").UpdateOne(r.Context(), bson.M{"handoffId": id}, bson.M{"$set": set})
	entry := timelineEntry(actor, "handoff_"+status, "sample", asString(h["sampleId"]), bson.M{"handoffId": id, "currentHolderId": holder})
	a.appendTimeline(r.Context(), asString(h["sampleId"]), entry)
	out := bson.M{"handoffId": id, "status": status, "senderConfirmed": sender, "receiverConfirmed": receiver, "currentHolderId": holder}
	a.saveIdempotent(r.Context(), actor, "confirm_handoff", bson.M(body), out)
	a.audit(r.Context(), actor, "confirm_handoff", "handoff", id, true, out)
	return out, 201, nil
}

