func (a *App) handleReroute(_ http.ResponseWriter,r *http.Request,actor *Actor,body bsonMap)(any,int,*apiError){if old,ok,e:=a.idempotent(r.Context(),actor,"reroute_journey",bson.M(body));e!=nil{return nil,0,e}else if ok{return old,201,nil};a.mu.Lock();defer a.mu.Unlock();j,e:=a.activeJourney(r.Context(),asString(body["journeyId"]),asInt(body["expectedPlanVersion"]));if e!=nil{return nil,0,e};replacement,status:=a.replaceJourney(r,actor,j);out:=bson.M{"journeyId":j["journeyId"],"replanStatus":status};if replacement!=nil{out["replacementPlanId"]=replacement["journeyId"];out["replacementJourney"]=journeyDTO(replacement)};a.saveIdempotent(r.Context(),actor,"reroute_journey",bson.M(body),out);a.audit(r.Context(),actor,"reroute_journey","journey",asString(j["journeyId"]),true,out);return out,201,nil}

func (a *App) handleDisruption(_ http.ResponseWriter,r *http.Request,actor *Actor,body bsonMap)(any,int,*apiError){if old,ok,e:=a.idempotent(r.Context(),actor,"report_disruption",bson.M(body));e!=nil{return nil,0,e}else if ok{return old,201,nil};a.mu.Lock();defer a.mu.Unlock();id:=uuid();resourceID:=asString(body["resourceId"]);affected:=[]string{};replacementIDs:=[]string{};status:="not_required";journeys:=a.findAll(r.Context(),"journeys",bson.M{"status":"active"});for _,j:=range journeys{involved:=asString(body["resourceType"])=="route"&&asString(j["journeyId"])==resourceID;if !involved{for _,x:=range a.findAll(r.Context(),"assignments",bson.M{"journeyId":j["journeyId"]}){if asString(x["workerId"])==resourceID||asString(x["fromLocationId"])==resourceID||asString(x["toLocationId"])==resourceID{involved=true;break}}};if involved{clone,s:=a.replaceJourney(r,actor,j);status=s;affected=append(affected,stringSlice(j["sampleIds"])...);if clone!=nil{replacementIDs=append(replacementIDs,asString(clone["journeyId"]))}}};d:=bson.M{"disruptionId":id,"resourceType":asString(body["resourceType"]),"resourceId":resourceID,"reason":asString(body["reason"]),"occurredAt":asString(body["occurredAt"]),"affectedSampleIds":affected,"replacementPlanIds":replacementIDs,"replanStatus":status};_,_=a.db.Collection("disruptions").InsertOne(r.Context(),d);out:=bson.M{"disruptionId":id,"affectedSampleIds":affected,"replacementPlanIds":replacementIDs,"replanStatus":status};a.saveIdempotent(r.Context(),actor,"report_disruption",bson.M(body),out);a.audit(r.Context(),actor,"report_disruption","disruption",id,true,out);return out,201,nil}

