package main

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"math"
	"net/http"
	"os"
	"sort"
	"strings"
	"sync"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo"
	"go.mongodb.org/mongo-driver/v2/mongo/options"
)

const dbName = "lab_logistics"

var collectionNames = []string{"users", "sessions", "sample_types", "locations", "connections", "capacities", "requests", "samples", "journeys", "assignments", "handoffs", "checkpoints", "exceptions", "disruptions", "audits", "events", "idempotency", "metadata"}

var validRoles = map[string]bool{
	"administrator": true, "dispatcher": true, "requester": true,
	"collection_professional": true, "delivery_partner": true,
	"node_handler": true, "laboratory_team": true,
}

var rolePermissions = map[string]map[string]bool{
	"administrator": {"*": true},
	"dispatcher": {
		"read_operations_state": true, "read_sample_state": true, "read_sample_lifecycle": true,
		"read_journey_plan": true, "search_audit_trail": true, "list_role_work": true,
		"cancel_journey": true, "edit_active_plan": true, "merge_journeys": true,
		"split_journey": true, "reroute_journey": true, "report_disruption": true,
		"set_worker_availability": true, "stream_realtime_events": true, "read_ui_bootstrap": true,
	},
	"requester": {
		"check_serviceability": true, "create_collection_request": true, "read_sample_state": true,
		"read_sample_lifecycle": true, "read_journey_plan": true, "list_role_work": true,
		"stream_realtime_events": true, "read_ui_bootstrap": true,
	},
	"collection_professional": workerPermissions(true),
	"delivery_partner":        workerPermissions(true),
	"node_handler":            workerPermissions(true),
	"laboratory_team":         workerPermissions(true),
}

func workerPermissions(presealed bool) map[string]bool {
	p := map[string]bool{
		"accept_assignment": true, "decline_assignment": true, "list_role_work": true,
		"read_sample_state": true, "read_sample_lifecycle": true, "read_journey_plan": true,
		"record_worker_location": true, "update_assignment_progress": true,
		"initiate_handoff": true, "confirm_handoff": true, "record_handling_checkpoint": true,
		"set_worker_availability": true, "stream_realtime_events": true, "read_ui_bootstrap": true,
	}
	if presealed {
		p["ingest_presealed_sample"] = true
	}
	return p
}

func init() {
	rolePermissions["collection_professional"]["collect_and_seal_sample"] = true
	rolePermissions["node_handler"]["configure_capacity"] = true
	rolePermissions["laboratory_team"]["configure_capacity"] = true
	rolePermissions["laboratory_team"]["confirm_laboratory_receipt"] = true
	rolePermissions["laboratory_team"]["record_laboratory_exception"] = true
}

type App struct {
	client *mongo.Client
	db     *mongo.Database
	webDir string
	mu     sync.Mutex
}

type Actor struct {
	UserID             string
	Username           string
	Roles              []string
	ActiveRole         string
	AssignedLocationID string
	SessionToken       string
}

type apiError struct {
	Status        int
	Code, Message string
}

func (e *apiError) Error() string                     { return e.Message }
func fail(status int, code, message string) *apiError { return &apiError{status, code, message} }

func newApp(ctx context.Context) (*App, error) {
	uri := os.Getenv("MONGODB_URI")
	if uri == "" {
		uri = "mongodb://127.0.0.1:27017"
	}
	client, err := mongo.Connect(options.Client().ApplyURI(uri))
	if err != nil {
		return nil, err
	}
	if err = client.Ping(ctx, nil); err != nil {
		return nil, err
	}
	a := &App{client: client, db: client.Database(dbName), webDir: "/workspace/frontend/dist"}
	if err = a.ensureAdmin(ctx); err != nil {
		return nil, err
	}
	return a, nil
}

func uuid() string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	h := hex.EncodeToString(b)
	return h[:8] + "-" + h[8:12] + "-" + h[12:16] + "-" + h[16:20] + "-" + h[20:]
}
func token() string {
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	return base64.RawURLEncoding.EncodeToString(b)
}
func passwordHash(username, password string) string {
	h := sha256.Sum256([]byte("lab-logistics:" + strings.ToLower(username) + ":" + password))
	return hex.EncodeToString(h[:])
}
func now() string { return time.Now().UTC().Format(time.RFC3339Nano) }

func (a *App) ensureAdmin(ctx context.Context) error {
	count, err := a.db.Collection("users").CountDocuments(ctx, bson.M{})
	if err != nil {
		return err
	}
	if count > 0 {
		return nil
	}
	username, password := os.Getenv("ADMIN_USERNAME"), os.Getenv("ADMIN_PASSWORD")
	if username == "" {
		username = "admin"
	}
	if password == "" {
		password = "admin"
	}
	_, err = a.db.Collection("users").InsertOne(ctx, bson.M{
		"userId": uuid(), "username": username, "usernameLower": strings.ToLower(username),
		"passwordHash": passwordHash(username, password), "fullName": "System Administrator",
		"email": "", "phone": "", "roles": bson.A{"administrator"}, "qualifications": bson.A{},
		"certifications": bson.A{}, "active": true, "available": true, "capacityUnits": 1,
		"assignmentCount": 0, "createdAt": now(),
	})
	return err
}

func (a *App) authenticate(r *http.Request) (*Actor, *apiError) {
	h := r.Header.Get("Authorization")
	if !strings.HasPrefix(h, "Bearer ") {
		return nil, fail(401, "unauthorized", "Authentication required")
	}
	t := strings.TrimSpace(strings.TrimPrefix(h, "Bearer "))
	var session bson.M
	if err := a.db.Collection("sessions").FindOne(r.Context(), bson.M{"token": t}).Decode(&session); err != nil {
		return nil, fail(401, "unauthorized", "Invalid session")
	}
	var user bson.M
	if err := a.db.Collection("users").FindOne(r.Context(), bson.M{"userId": asString(session["userId"]), "active": true}).Decode(&user); err != nil {
		return nil, fail(401, "unauthorized", "Account unavailable")
	}
	return &Actor{UserID: asString(user["userId"]), Username: asString(user["username"]), Roles: stringSlice(user["roles"]), ActiveRole: asString(session["activeRole"]), AssignedLocationID: asString(user["assignedLocationId"]), SessionToken: t}, nil
}

func (a *App) authorize(actor *Actor, operation string) *apiError {
	if actor.ActiveRole == "" {
		return fail(409, "role_not_selected", "Select an active role")
	}
	if !contains(actor.Roles, actor.ActiveRole) {
		return fail(403, "forbidden", "Role is not assigned")
	}
	p := rolePermissions[actor.ActiveRole]
	if p == nil || (!p["*"] && !p[operation]) {
		return fail(403, "forbidden", "Action is not permitted for the selected role")
	}
	return nil
}

func asString(v any) string {
	if s, ok := v.(string); ok {
		return s
	}
	return ""
}
func asBool(v any) bool {
	if b, ok := v.(bool); ok {
		return b
	}
	return false
}
func asFloat(v any) float64 {
	switch x := v.(type) {
	case float64:
		return x
	case int32:
		return float64(x)
	case int64:
		return float64(x)
	case int:
		return float64(x)
	}
	return 0
}
func asInt(v any) int { return int(asFloat(v)) }
func stringSlice(v any) []string {
	out := []string{}
	switch a := v.(type) {
	case bson.A:
		for _, x := range a {
			out = append(out, asString(x))
		}
	case []string:
		return a
	case []any:
		for _, x := range a {
			out = append(out, asString(x))
		}
	}
	return out
}
func contains(a []string, s string) bool {
	for _, x := range a {
		if x == s {
			return true
		}
	}
	return false
}
func coordinate(v any) bson.M {
	switch x := v.(type) {
	case bson.M:
		return x
	case map[string]any:
		return bson.M(x)
	case bson.D:
		return x.Map()
	}
	return bson.M{}
}
func dateValue(v any) (time.Time, error) {
	s := asString(v)
	if s == "" {
		return time.Time{}, errors.New("missing time")
	}
	return time.Parse(time.RFC3339, s)
}
func stale(recorded any) bool {
	t, e := dateValue(recorded)
	return e != nil || time.Since(t) > 10*time.Minute
}

func (a *App) audit(ctx context.Context, actor *Actor, action, entityType, entityID string, success bool, details any) {
	role, uid := "system", "system"
	if actor != nil {
		role = actor.ActiveRole
		uid = actor.UserID
	}
	t := now()
	id := uuid()
	doc := bson.M{"auditId": id, "actorId": uid, "role": role, "actorRole": role, "action": action, "entityType": entityType, "entityId": entityID, "success": success, "occurredAt": t, "details": details}
	_, _ = a.db.Collection("audits").InsertOne(ctx, doc)
	seq, _ := a.db.Collection("events").CountDocuments(ctx, bson.M{})
	_, _ = a.db.Collection("events").InsertOne(ctx, bson.M{"id": seq + 1, "eventId": uuid(), "type": action, "entityType": entityType, "entityId": entityID, "payload": details, "createdAt": t, "audienceRole": role})
}

func timelineEntry(actor *Actor, action, entityType, entityID string, details any) bson.M {
	role, uid := "system", "system"
	if actor != nil {
		role = actor.ActiveRole
		uid = actor.UserID
	}
	return bson.M{"eventId": uuid(), "action": action, "actorId": uid, "role": role, "entityType": entityType, "entityId": entityID, "success": true, "occurredAt": now(), "details": details}
}
func (a *App) appendTimeline(ctx context.Context, sampleID string, entry bson.M) {
	_, _ = a.db.Collection("samples").UpdateOne(ctx, bson.M{"sampleId": sampleID}, bson.M{"$push": bson.M{"timeline": entry}})
}

func (a *App) idempotent(ctx context.Context, actor *Actor, op string, body bson.M) (bson.M, bool, *apiError) {
	key := asString(body["idempotencyKey"])
	if key == "" {
		return nil, false, fail(400, "idempotency_required", "An idempotency key is required")
	}
	var old bson.M
	err := a.db.Collection("idempotency").FindOne(ctx, bson.M{"actorId": actor.UserID, "operation": op, "key": key}).Decode(&old)
	if err == nil {
		return old["response"].(bson.M), true, nil
	}
	return nil, false, nil
}
func (a *App) saveIdempotent(ctx context.Context, actor *Actor, op string, body, response bson.M) {
	_, _ = a.db.Collection("idempotency").InsertOne(ctx, bson.M{"actorId": actor.UserID, "operation": op, "key": asString(body["idempotencyKey"]), "response": response, "createdAt": now()})
}

func distanceKm(a, b bson.M) float64 {
	lat1, lon1 := asFloat(a["latitude"])*math.Pi/180, asFloat(a["longitude"])*math.Pi/180
	lat2, lon2 := asFloat(b["latitude"])*math.Pi/180, asFloat(b["longitude"])*math.Pi/180
	dlat, dlon := lat2-lat1, lon2-lon1
	x := math.Sin(dlat/2)*math.Sin(dlat/2) + math.Cos(lat1)*math.Cos(lat2)*math.Sin(dlon/2)*math.Sin(dlon/2)
	return 6371 * 2 * math.Atan2(math.Sqrt(x), math.Sqrt(1-x))
}

type RouteResult struct {
	Serviceable            bool
	Reason, StartID, LabID string
	Connections            []bson.M
	Locations              []bson.M
	Minutes                int
	Cost                   float64
	Version                int
}

func (a *App) serviceability(ctx context.Context, body bson.M) RouteResult {
	result := RouteResult{Reason: "outside_service_coverage", Version: a.networkVersion(ctx)}
	var st bson.M
	if a.db.Collection("sample_types").FindOne(ctx, bson.M{"sampleTypeId": asString(body["sampleTypeId"])}).Decode(&st) != nil {
		result.Reason = "handling_rules_unsatisfiable"
		return result
	}
	origin := coordinate(body["origin"])
	originType := asString(body["originType"])
	if originType == "" {
		originType = "home"
	}
	locations := a.findAll(ctx, "locations", bson.M{"active": true})
	var starts []bson.M
	for _, l := range locations {
		funcs := coordinate(l["functions"])
		if !asBool(funcs["collection_point"]) {
			continue
		}
		if originType == "node" && asString(body["originNodeId"]) == asString(l["locationId"]) {
			starts = []bson.M{l}
			break
		}
		if distanceKm(origin, coordinate(l["coordinate"])) <= math.Min(5, asFloat(l["coverageKm"])) {
			starts = append(starts, l)
		}
	}
	if len(starts) == 0 {
		return result
	}
	accept := a.findAll(ctx, "capacities", bson.M{"kind": "laboratory_acceptance", "sampleTypeId": asString(body["sampleTypeId"]), "accepts": true})
	labs := map[string]bool{}
	for _, x := range accept {
		labs[asString(x["resourceId"])] = true
	}
	for _, l := range locations {
		if asBool(coordinate(l["functions"])["laboratory"]) {
			if len(accept) == 0 {
				labs[asString(l["locationId"])] = true
			}
		}
	}
	if len(labs) == 0 {
		result.Reason = "no_accepting_laboratory"
		return result
	}
	conns := a.findAll(ctx, "connections", bson.M{"active": true})
	cooled := asBool(st["requiresCooledRoute"])
	byFrom := map[string][]bson.M{}
	for _, c := range conns {
		if cooled && !asBool(c["cooled"]) {
			continue
		}
		cap := capacityOf(c)
		if (cooled && asInt(cap["cooledAvailableUnits"]) < 1) || (!cooled && asInt(cap["availableUnits"]) < 1) {
			continue
		}
		byFrom[asString(c["fromLocationId"])] = append(byFrom[asString(c["fromLocationId"])], c)
	}
	type node struct {
		id      string
		minutes int
		path    []bson.M
	}
	q := []node{}
	seen := map[string]int{}
	for _, s := range starts {
		q = append(q, node{asString(s["locationId"]), 0, nil})
		result.StartID = asString(s["locationId"])
	}
	var best *node
	for len(q) > 0 {
		sort.Slice(q, func(i, j int) bool { return q[i].minutes < q[j].minutes })
		cur := q[0]
		q = q[1:]
		if old, ok := seen[cur.id]; ok && old <= cur.minutes {
			continue
		}
		seen[cur.id] = cur.minutes
		if labs[cur.id] {
			x := cur
			best = &x
			break
		}
		for _, c := range byFrom[cur.id] {
			p := append(append([]bson.M{}, cur.path...), c)
			q = append(q, node{asString(c["toLocationId"]), cur.minutes + asInt(c["travelMinutes"]), p})
		}
	}
	if best == nil {
		result.Reason = "no_route"
		return result
	}
	requested, _ := dateValue(body["requestedAt"])
	earliest := requested
	if t, e := dateValue(body["earliestCollectionAt"]); e == nil {
		earliest = t
	}
	arrival := earliest.Add(time.Duration(best.minutes) * time.Minute)
	deadline, e := dateValue(body["deliveryDeadline"])
	if e != nil || arrival.After(deadline) {
		result.Reason = "deadline_unreachable"
		return result
	}
	result.Serviceable = true
	result.Reason = "serviceable"
	result.LabID = best.id
	result.Connections = best.path
	result.Minutes = best.minutes
	ids := []string{result.StartID}
	for _, c := range best.path {
		result.Cost += asFloat(c["costUnits"])
		ids = append(ids, asString(c["toLocationId"]))
	}
	for _, id := range ids {
		for _, l := range locations {
			if asString(l["locationId"]) == id {
				result.Locations = append(result.Locations, l)
				break
			}
		}
	}
	return result
}

func capacityOf(doc bson.M) bson.M {
	cap := coordinate(doc["capacity"])
	regular := asInt(cap["capacityUnits"])
	reserved := asInt(cap["reservedUnits"])
	cooled := asInt(cap["cooledCapacityUnits"])
	coolres := asInt(cap["cooledReservedUnits"])
	return bson.M{"capacityUnits": regular, "reservedUnits": reserved, "availableUnits": max(0, regular-reserved), "cooledCapacityUnits": cooled, "cooledReservedUnits": coolres, "cooledAvailableUnits": max(0, cooled-coolres)}
}

func (a *App) networkVersion(ctx context.Context) int {
	var m bson.M
	if a.db.Collection("metadata").FindOne(ctx, bson.M{"key": "network"}).Decode(&m) != nil {
		return 1
	}
	v := asInt(m["version"])
	if v < 1 {
		return 1
	}
	return v
}
func (a *App) bumpNetwork(ctx context.Context) {
	_, _ = a.db.Collection("metadata").UpdateOne(ctx, bson.M{"key": "network"}, bson.M{"$inc": bson.M{"version": 1}, "$set": bson.M{"computedAt": now(), "status": "complete"}}, options.UpdateOne().SetUpsert(true))
}
func (a *App) findAll(ctx context.Context, name string, filter bson.M) []bson.M {
	cur, e := a.db.Collection(name).Find(ctx, filter)
	if e != nil {
