	"delivery_partner":        workerPermissions(true),
	"node_handler":            workerPermissions(true),
	"laboratory_team":         workerPermissions(true),
}

func workerPermissions(presealed bool) map[string]bool {
	p := map[string]bool{
		"accept_assignment": true, "decline_assignment": true, "list_role_work": true,
		"read_sample_state": true, "read_sample_lifecycle": true, "read_journey_plan": true,
