package main

import (
	"context"
	"net/http"
	"sort"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo/options"
)

func validateRequestTimes(body bsonMap) *apiError {
	req, e1 := dateValue(body["requestedAt"])
	deadline, e2 := dateValue(body["deliveryDeadline"])
	if e1 != nil || e2 != nil {
		return fail(400, "invalid_time", "Times must use RFC 3339")
	}
	if !deadline.After(req) {
		return fail(400, "invalid_deadline", "Delivery deadline must follow request time")
	}
	earliest := req
	latest := deadline
	if v, ok := body["earliestCollectionAt"]; ok {
		var e error
		earliest, e = dateValue(v)
		if e != nil {
			return fail(400, "invalid_time", "Invalid collection time")
		}
	}
	if v, ok := body["latestCollectionAt"]; ok {
		var e error
		latest, e = dateValue(v)
		if e != nil {
			return fail(400, "invalid_time", "Invalid collection time")
		}
	}
	if latest.Before(earliest) || earliest.Before(req) || latest.After(deadline) {
		return fail(400, "invalid_collection_window", "Collection window is invalid")
	}
	return nil
}

func (a *App) handleCheckServiceability(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	if e := validateCoord(body["origin"]); e != nil {
		return nil, 0, fail(400, "invalid_origin", "Origin coordinate is invalid")
	}
	if e := validateRequestTimes(body); e != nil {
		return nil, 0, e
	}
	originType := asString(body["originType"])
	if originType == "" {
		originType = "home"
	}
	if originType != "home" && originType != "clinic" && originType != "node" {
		return nil, 0, fail(400, "invalid_origin_type", "Invalid origin type")
	}
	beforeReq, _ := a.db.Collection("requests").CountDocuments(r.Context(), bson.M{})
	beforeSamples, _ := a.db.Collection("samples").CountDocuments(r.Context(), bson.M{})
	res := a.serviceability(r.Context(), bson.M(body))
	out := bson.M{"serviceable": res.Serviceable, "reason": res.Reason, "serviceabilityVersion": res.Version}
	if res.Serviceable {
		requested, _ := dateValue(body["requestedAt"])
		if t, e := dateValue(body["earliestCollectionAt"]); e == nil {
			requested = t
		}
		out["targetLaboratoryId"] = res.LabID
		out["estimatedArrivalAt"] = requested.Add(time.Duration(res.Minutes) * time.Minute).UTC().Format(time.RFC3339Nano)
	}
	a.audit(r.Context(), actor, "check_serviceability", "network", "serviceability", true, bson.M{"result": res.Reason, "requestCount": beforeReq, "sampleCount": beforeSamples})
	return out, 200, nil
}

func (a *App) handleCreateRequest(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	return a.createRequest(r, actor, body, false)
}
func (a *App) handlePresealed(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	if asString(body["originType"]) == "home" || asString(body["originType"]) == "" {
		return nil, 0, fail(400, "invalid_origin_type", "Pre-sealed samples must originate at a clinic or node")
	}
	return a.createRequest(r, actor, body, true)
}

func (a *App) createRequest(r *http.Request, actor *Actor, body bsonMap, sealed bool) (any, int, *apiError) {
	if e := validateCoord(body["origin"]); e != nil {
		return nil, 0, fail(400, "invalid_origin", "Origin coordinate is invalid")
	}
	if e := validateRequestTimes(body); e != nil {
		return nil, 0, e
	}
	if key := asString(body["idempotencyKey"]); key != "" {
		if old, ok, e := a.idempotent(r.Context(), actor, map[bool]string{true: "ingest_presealed_sample", false: "create_collection_request"}[sealed], bson.M(body)); e != nil {
			return nil, 0, e
		} else if ok {
			return old, 201, nil
		}
	}
	requester := actor.UserID
	if v := asString(body["requesterId"]); v != "" && (actor.ActiveRole == "administrator" || actor.ActiveRole == "dispatcher") {
		requester = v
	}
	originType := asString(body["originType"])
	if originType == "" {
		originType = "home"
	}
	if originType == "node" && asString(body["originNodeId"]) == "" {
		return nil, 0, fail(400, "invalid_origin", "Node origin requires originNodeId")
	}
	var st bson.M
	if a.db.Collection("sample_types").FindOne(r.Context(), bson.M{"sampleTypeId": asString(body["sampleTypeId"]), "active": true}).Decode(&st) != nil {
		return nil, 0, fail(404, "not_found", "Sample type not found")
	}
	if asString(body["containerType"]) != asString(st["containerType"]) {
		return nil, 0, fail(400, "handling_noncompliant", "Container does not match the sample type")
	}
	if asFloat(body["temperatureMinC"]) < asFloat(st["temperatureMinC"]) || asFloat(body["temperatureMaxC"]) > asFloat(st["temperatureMaxC"]) {
		return nil, 0, fail(400, "handling_noncompliant", "Temperature requirements do not satisfy the sample type")
	}
	res := a.serviceability(r.Context(), bson.M(body))
	reqID, sampleID := uuid(), uuid()
	requested, _ := dateValue(body["requestedAt"])
	deadline, _ := dateValue(body["deliveryDeadline"])
	earliest := requested
	latest := deadline
	if t, e := dateValue(body["earliestCollectionAt"]); e == nil {
		earliest = t
	}
	if t, e := dateValue(body["latestCollectionAt"]); e == nil {
		latest = t
	}
	service := "unserviceable"
	if res.Serviceable {
		service = "serviceable"
	}
	status := "requested"
	if sealed {
		status = "sealed"
	}
	entry := timelineEntry(actor, map[bool]string{true: "presealed_sample_registered", false: "collection_requested"}[sealed], "sample", sampleID, bson.M{"serviceability": service})
	sample := bson.M{"sampleId": sampleID, "requestId": reqID, "requesterId": requester, "origin": toBson(body["origin"]), "originType": originType, "originNodeId": asString(body["originNodeId"]), "requestedAt": requested.UTC().Format(time.RFC3339Nano), "deliveryDeadline": deadline.UTC().Format(time.RFC3339Nano), "earliestCollectionAt": earliest.UTC().Format(time.RFC3339Nano), "latestCollectionAt": latest.UTC().Format(time.RFC3339Nano), "sampleTypeId": asString(body["sampleTypeId"]), "containerType": asString(body["containerType"]), "temperatureMinC": asFloat(body["temperatureMinC"]), "temperatureMaxC": asFloat(body["temperatureMaxC"]), "incompatibleSampleTypes": stringsFromAny(body["incompatibleSampleTypes"]), "serviceability": service, "serviceabilityReason": res.Reason, "status": status, "sealed": sealed, "activeAssignmentIds": bson.A{}, "completedLegIds": bson.A{}, "activeReplacementPlanIds": bson.A{}, "timeline": bson.A{entry}, "locationStale": false}
	if sealed {
		sample["currentHolderId"] = actor.UserID
		sample["latestLocation"] = toBson(body["origin"])
		sample["locationRecordedAt"] = now()
	}
	request := bson.M{"requestId": reqID, "sampleId": sampleID, "requesterId": requester, "status": status, "createdAt": now()}
	_, _ = a.db.Collection("requests").InsertOne(r.Context(), request)
	_, _ = a.db.Collection("samples").InsertOne(r.Context(), sample)
	active := []string{}
	journeyID := ""
	if res.Serviceable {
		journeyID, active = a.buildJourney(r, actor, sample, st, res, sealed)
		_, _ = a.db.Collection("samples").UpdateOne(r.Context(), bson.M{"sampleId": sampleID}, bson.M{"$set": bson.M{"activeJourneyId": journeyID, "targetLaboratoryId": res.LabID, "activeAssignmentIds": active}})
	}
	out := bson.M{"requestId": reqID, "sampleId": sampleID, "serviceability": service, "serviceabilityReason": res.Reason, "activeAssignmentIds": active, "earliestCollectionAt": earliest.UTC().Format(time.RFC3339Nano), "latestCollectionAt": latest.UTC().Format(time.RFC3339Nano), "alreadySealed": sealed, "originType": originType}
	if journeyID != "" {
		out["journeyId"] = journeyID
		out["targetLaboratoryId"] = res.LabID
	}
	op := map[bool]string{true: "ingest_presealed_sample", false: "create_collection_request"}[sealed]
	a.audit(r.Context(), actor, op, "sample", sampleID, true, out)
	if asString(body["idempotencyKey"]) != "" {
		a.saveIdempotent(r.Context(), actor, op, bson.M(body), out)
	}
	return out, 201, nil
}

func (a *App) buildJourney(r *http.Request, actor *Actor, sample, st bson.M, res RouteResult, sealed bool) (string, []string) {
	journeyID := uuid()
	assignments := []bson.M{}
	collectionIDs, nodeIDs, labIDs := []string{}, []string{}, []string{}
	active := []string{}
	assignedWorkers := []string{}
	add := func(kind, role, from, to, node string, sequence int) bson.M {
		id := uuid()
		worker := a.selectWorker(r, role, node, st, nil)
		status := "unassigned"
		expiry := ""
		if worker != "" {
			status = "offered"
			expiry = time.Now().UTC().Add(15 * time.Minute).Format(time.RFC3339Nano)
			assignedWorkers = append(assignedWorkers, worker)
		}
		h := bson.A{timelineEntry(actor, "assignment_created", "assignment", id, bson.M{"kind": kind, "status": status})}
		x := bson.M{"assignmentId": id, "sampleId": sample["sampleId"], "journeyId": journeyID, "kind": kind, "requiredRole": role, "fromLocationId": from, "toLocationId": to, "nodeId": node, "sequence": sequence, "status": status, "workerId": worker, "offerExpiresAt": expiry, "history": h, "declinedBy": bson.A{}, "active": true}
		_, _ = a.db.Collection("assignments").InsertOne(r.Context(), x)
		if worker != "" {
			_, _ = a.db.Collection("users").UpdateOne(r.Context(), bson.M{"userId": worker}, bson.M{"$inc": bson.M{"assignmentCount": 1}, "$set": bson.M{"recentAssignedAt": now()}})
		}
		assignments = append(assignments, x)
		active = append(active, id)
		return x
	}
	seq := 0
	if !sealed {
		x := add("collection", "collection_professional", asString(sample["originNodeId"]), res.StartID, "", seq)
		collectionIDs = append(collectionIDs, asString(x["assignmentId"]))
		seq++
	}
	for i, c := range res.Connections {
		x := add("transport", "delivery_partner", asString(c["fromLocationId"]), asString(c["toLocationId"]), "", seq)
		seq++
		if i == 0 {
		}
		_ = x
		if i < len(res.Connections)-1 {
			n := add("node", "node_handler", asString(c["fromLocationId"]), asString(c["toLocationId"]), asString(c["toLocationId"]), seq)
			nodeIDs = append(nodeIDs, asString(n["assignmentId"]))
			seq++
		}
	}
	lab := add("laboratory", "laboratory_team", res.LabID, res.LabID, res.LabID, seq)
	labIDs = append(labIDs, asString(lab["assignmentId"]))
	stops := bson.A{}
	base, _ := dateValue(sample["earliestCollectionAt"])
	minutes := 0
	for i, l := range res.Locations {
		if i > 0 {
			minutes += asInt(res.Connections[i-1]["travelMinutes"])
		}
		stopType := "transfer"
		if i == 0 {
			stopType = "collection"
		}
		if i == len(res.Locations)-1 {
			stopType = "laboratory"
		}
		stops = append(stops, bson.M{"stopId": uuid(), "locationId": asString(l["locationId"]), "stopType": stopType, "sequence": i, "estimatedAt": base.Add(time.Duration(minutes) * time.Minute).UTC().Format(time.RFC3339Nano), "dwellMinutes": asInt(l["handlingMinutes"]), "coordinate": coordinate(l["coordinate"])})
	}
	legs := bson.A{}
	transport := []bson.M{}
	for _, x := range assignments {
		if asString(x["kind"]) == "transport" {
			transport = append(transport, x)
		}
	}
	for i, x := range transport {
		leg := bson.M{"assignmentId": asString(x["assignmentId"]), "sequence": i, "status": asString(x["status"]), "fromLocationId": asString(x["fromLocationId"]), "toLocationId": asString(x["toLocationId"]), "sampleId": asString(sample["sampleId"])}
		if asString(x["workerId"]) != "" {
			leg["workerId"] = x["workerId"]
		}
		legs = append(legs, leg)
	}
	mode := "direct"
	if len(res.Connections) > 1 {
		mode = "multi_stop"
	}
	journey := bson.M{"journeyId": journeyID, "planVersion": 1, "routeMode": mode, "status": "active", "estimatedDeliveryAt": base.Add(time.Duration(res.Minutes) * time.Minute).UTC().Format(time.RFC3339Nano), "totalCostUnits": res.Cost, "capacityUsed": 1, "capacityAvailable": 1, "sampleIds": bson.A{sample["sampleId"]}, "orderedStops": stops, "legs": legs, "assignedWorkerIds": assignedWorkers, "collectionAssignmentIds": collectionIDs, "nodeAssignmentIds": nodeIDs, "laboratoryAssignmentIds": labIDs, "valid": true, "createdAt": now()}
	if len(collectionIDs) > 0 {
		journey["collectionAssignmentId"] = collectionIDs[0]
	}
	if len(transport) > 0 {
		journey["firstTransportAssignmentId"] = transport[0]["assignmentId"]
		journey["finalTransportAssignmentId"] = transport[len(transport)-1]["assignmentId"]
	}
	if len(transport) > 2 {
		journey["middleTransportAssignmentId"] = transport[1]["assignmentId"]
	}
	_, _ = a.db.Collection("journeys").InsertOne(r.Context(), journey)
	a.reserveRoute(r.Context(), res, st, 1)
	return journeyID, active
}

func (a *App) selectWorker(r *http.Request, role, node string, st bson.M, excluded []string) string {
	filter := bson.M{"roles": role, "active": true, "available": true}
	if role == "node_handler" || role == "laboratory_team" {
		filter["assignedLocationId"] = node
	}
	users := a.findAll(r.Context(), "users", filter)
	sort.Slice(users, func(i, j int) bool {
		pi, pj := asInt(users[i]["declinePenalty"]), asInt(users[j]["declinePenalty"])
		if pi != pj {
			return pi < pj
		}
		return asInt(users[i]["assignmentCount"]) < asInt(users[j]["assignmentCount"])
	})
	for _, u := range users {
		id := asString(u["userId"])
		if contains(excluded, id) {
			continue
		}
		if role == "collection_professional" && asBool(st["qualifiedCollectorRequired"]) {
			qual := asString(st["requiredQualification"])
			if !contains(stringSlice(u["qualifications"]), qual) && !hasActiveCertification(u["certifications"], qual) {
				continue
			}
		}
		return id
	}
	return ""
}
func hasActiveCertification(v any, code string) bool {
	switch a := v.(type) {
	case bson.A:
		for _, x := range a {
			m := toBson(x)
			if asString(m["code"]) == code && asBool(m["active"]) {
				if exp := asString(m["expiresAt"]); exp == "" {
					return true
				}
				t, e := time.Parse(time.RFC3339, exp)
				if e == nil && t.After(time.Now()) {
					return true
				}
			}
		}
	case []any:
		for _, x := range a {
			if hasActiveCertification(bson.A{x}, code) {
				return true
			}
		}
	}
	return false
}
func (a *App) reserveRoute(ctx context.Context, res RouteResult, st bson.M, units int) {
	field := "capacity.reservedUnits"
	if asBool(st["requiresCooledRoute"]) {
		field = "capacity.cooledReservedUnits"
	}
	for _, c := range res.Connections {
		_, _ = a.db.Collection("connections").UpdateOne(ctx, bson.M{"connectionId": c["connectionId"]}, bson.M{"$inc": bson.M{field: units}})
	}
	for _, l := range res.Locations {
		_, _ = a.db.Collection("locations").UpdateOne(ctx, bson.M{"locationId": l["locationId"]}, bson.M{"$inc": bson.M{field: units}})
	}
}

func (a *App) handleAcceptAssignment(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
