	out := bson.M{"assignmentId": id, "workerId": actor.UserID, "status": "accepted"}
	a.saveIdempotent(r.Context(), actor, "accept_assignment", bson.M(body), out)
	a.audit(r.Context(), actor, "accept_assignment", "assignment", id, true, out)
	return out, 201, nil
