func (a *App) handleCollectSeal(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	if old, ok, e := a.idempotent(r.Context(), actor, "collect_and_seal_sample", bson.M(body)); e != nil {
		return nil, 0, e
	} else if ok {
		return old, 201, nil
	}
	x, e := a.ownedAssignment(r.Context(), actor, asString(body["assignmentId"]))
	if e != nil {
		return nil, 0, e
	}
	if asString(x["kind"]) != "collection" || asString(x["status"]) != "accepted" {
		return nil, 0, fail(409, "collection_not_ready", "Collection assignment is not accepted")
	}
	var s bson.M
	if a.db.Collection("samples").FindOne(r.Context(), bson.M{"sampleId": asString(body["sampleId"])}).Decode(&s) != nil {
		return nil, 0, fail(404, "not_found", "Sample not found")
	}
	collected, e2 := dateValue(body["collectedAt"])
	early, _ := dateValue(s["earliestCollectionAt"])
	late, _ := dateValue(s["latestCollectionAt"])
	if e2 != nil {
		return nil, 0, fail(400, "invalid_time", "Invalid collection time")
	}
	if collected.Before(early) || collected.After(late) {
		return nil, 0, fail(409, "outside_collection_window", "Collection is outside the requested window")
	}
	compliant := asString(body["containerType"]) == asString(s["containerType"]) && asFloat(body["observedTemperatureC"]) >= asFloat(s["temperatureMinC"]) && asFloat(body["observedTemperatureC"]) <= asFloat(s["temperatureMaxC"])
	entry := timelineEntry(actor, "sample_collected_and_sealed", "sample", asString(s["sampleId"]), bson.M{"handlingCompliant": compliant})
	status := "sealed"
	set := bson.M{"sealed": true, "status": status, "currentHolderId": actor.UserID, "locationRecordedAt": collected.UTC().Format(time.RFC3339Nano), "latestLocation": s["origin"]}
	if !compliant {
		set["status"] = "exception"
		set["exception"] = bson.M{"reason": "handling_noncompliant", "observedAt": collected.UTC().Format(time.RFC3339Nano)}
	}
	_, _ = a.db.Collection("samples").UpdateOne(r.Context(), bson.M{"sampleId": s["sampleId"], "sealed": false}, bson.M{"$set": set, "$push": bson.M{"timeline": entry}})
	_, _ = a.db.Collection("assignments").UpdateOne(r.Context(), bson.M{"assignmentId": x["assignmentId"]}, bson.M{"$set": bson.M{"status": "completed", "active": false}, "$push": bson.M{"history": entry}})
	out := bson.M{"sampleId": s["sampleId"], "status": "sealed", "currentHolderId": actor.UserID, "sealedAt": collected.UTC().Format(time.RFC3339Nano), "handlingCompliant": compliant}
	a.saveIdempotent(r.Context(), actor, "collect_and_seal_sample", bson.M(body), out)
	a.audit(r.Context(), actor, "collect_and_seal_sample", "sample", asString(s["sampleId"]), true, out)
	return out, 201, nil
}

