	}
	id := uuid()
	h := bson.M{"handoffId": id, "sampleId": sampleID, "fromAssignmentId": asString(body["fromAssignmentId"]), "toAssignmentId": asString(body["toAssignmentId"]), "senderId": actor.UserID, "receiverId": receiver, "senderConfirmed": false, "receiverConfirmed": false, "status": "pending", "initiatedAt": asString(body["initiatedAt"])}
	_, _ = a.db.Collection("handoffs").InsertOne(r.Context(), h)
	_, _ = a.db.Collection("samples").UpdateOne(r.Context(), bson.M{"sampleId": sampleID}, bson.M{"$set": bson.M{"pendingHandoffId": id}})
	out := bson.M{"handoffId": id, "senderId": actor.UserID, "receiverId": receiver, "currentHolderId": actor.UserID, "status": "pending"}
