		return nil, 0, fail(404, "not_found", "Sample not found")
	}
	if asString(s["currentHolderId"]) != actor.UserID {
		return nil, 0, fail(409, "custody_required", "Current custody is required")
	}
	compliant := asString(body["containerType"]) == asString(s["containerType"]) && asFloat(body["observedTemperatureC"]) >= asFloat(s["temperatureMinC"]) && asFloat(body["observedTemperatureC"]) <= asFloat(s["temperatureMaxC"])
	id := uuid()
	cp := bson.M{"checkpointId": id, "sampleId": s["sampleId"], "assignmentId": asString(body["assignmentId"]), "containerType": asString(body["containerType"]), "observedTemperatureC": asFloat(body["observedTemperatureC"]), "recordedAt": asString(body["recordedAt"]), "compliant": compliant, "holderId": actor.UserID}
	_, _ = a.db.Collection("checkpoints").InsertOne(r.Context(), cp)
	status := asString(s["status"])
	if !compliant {
		status = "exception"
		ex := bson.M{"exceptionId": uuid(), "sampleId": s["sampleId"], "reason": "handling_noncompliant", "observedAt": asString(body["recordedAt"])}
		_, _ = a.db.Collection("exceptions").InsertOne(r.Context(), ex)
		_, _ = a.db.Collection("samples").UpdateOne(r.Context(), bson.M{"sampleId": s["sampleId"]}, bson.M{"$set": bson.M{"status": "exception", "exception": ex}})
	}
	entry := timelineEntry(actor, "handling_checkpoint", "sample", asString(s["sampleId"]), cp)
	a.appendTimeline(r.Context(), asString(s["sampleId"]), entry)
	out := bson.M{"checkpointId": id, "sampleId": s["sampleId"], "compliant": compliant, "sampleStatus": status}
	a.saveIdempotent(r.Context(), actor, "record_handling_checkpoint", bson.M(body), out)
	a.audit(r.Context(), actor, "record_handling_checkpoint", "sample", asString(s["sampleId"]), true, out)
	return out, 201, nil
}

func (a *App) handleLabReceipt(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	if old, ok, e := a.idempotent(r.Context(), actor, "confirm_laboratory_receipt", bson.M(body)); e != nil {
		return nil, 0, e
	} else if ok {
		return old, 201, nil
	}
	lab := asString(body["laboratoryId"])
	if actor.AssignedLocationID != "" && actor.AssignedLocationID != lab {
		return nil, 0, fail(403, "wrong_laboratory", "Operator is assigned to another laboratory")
	}
	var s bson.M
	if a.db.Collection("samples").FindOne(r.Context(), bson.M{"sampleId": asString(body["sampleId"])}).Decode(&s) != nil {
		return nil, 0, fail(404, "not_found", "Sample not found")
	}
	if asString(s["targetLaboratoryId"]) != lab {
		return nil, 0, fail(409, "laboratory_not_accepting", "Sample is not expected at this laboratory")
	}
	received, e2 := dateValue(body["receivedAt"])
	if e2 != nil {
		return nil, 0, fail(400, "invalid_time", "Invalid receipt time")
	}
	entry := timelineEntry(actor, "laboratory_received", "sample", asString(s["sampleId"]), bson.M{"laboratoryId": lab})
	_, _ = a.db.Collection("samples").UpdateOne(r.Context(), bson.M{"sampleId": s["sampleId"]}, bson.M{"$set": bson.M{"status": "received", "receivedLaboratoryId": lab, "currentHolderId": actor.UserID, "receivedAt": received.UTC().Format(time.RFC3339Nano)}, "$push": bson.M{"timeline": entry}})
	_, _ = a.db.Collection("journeys").UpdateOne(r.Context(), bson.M{"journeyId": s["activeJourneyId"]}, bson.M{"$set": bson.M{"status": "completed"}})
	_, _ = a.db.Collection("requests").UpdateOne(r.Context(), bson.M{"requestId": s["requestId"]}, bson.M{"$set": bson.M{"status": "completed"}})
	out := bson.M{"sampleId": s["sampleId"], "laboratoryId": lab, "status": "received", "receivedAt": received.UTC().Format(time.RFC3339Nano)}
	a.saveIdempotent(r.Context(), actor, "confirm_laboratory_receipt", bson.M(body), out)
	a.audit(r.Context(), actor, "confirm_laboratory_receipt", "sample", asString(s["sampleId"]), true, out)
	return out, 201, nil
}

func (a *App) handleLabException(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	if old, ok, e := a.idempotent(r.Context(), actor, "record_laboratory_exception", bson.M(body)); e != nil {
		return nil, 0, e
	} else if ok {
		return old, 201, nil
	}
	lab := asString(body["laboratoryId"])
	if actor.AssignedLocationID != "" && actor.AssignedLocationID != lab {
		return nil, 0, fail(403, "wrong_laboratory", "Operator is assigned elsewhere")
	}
	id := uuid()
	ex := bson.M{"exceptionId": id, "sampleId": asString(body["sampleId"]), "laboratoryId": lab, "reason": asString(body["reason"]), "observedAt": asString(body["observedAt"]), "status": "open"}
	if res, _ := a.db.Collection("samples").UpdateOne(r.Context(), bson.M{"sampleId": body["sampleId"]}, bson.M{"$set": bson.M{"status": "exception", "exception": ex}}); res.MatchedCount == 0 {
		return nil, 0, fail(404, "not_found", "Sample not found")
	}
	_, _ = a.db.Collection("exceptions").InsertOne(r.Context(), ex)
	entry := timelineEntry(actor, "laboratory_exception", "sample", asString(body["sampleId"]), ex)
	a.appendTimeline(r.Context(), asString(body["sampleId"]), entry)
	out := bson.M{"exceptionId": id, "sampleId": body["sampleId"], "status": "exception", "reason": body["reason"]}
	a.saveIdempotent(r.Context(), actor, "record_laboratory_exception", bson.M(body), out)
	a.audit(r.Context(), actor, "record_laboratory_exception", "sample", asString(body["sampleId"]), true, out)
	return out, 201, nil
}

