	_, _ = a.db.Collection("users").UpdateOne(r.Context(), bson.M{"userId": actor.UserID}, bson.M{"$set": bson.M{"latestLocation": coord, "locationRecordedAt": recorded.UTC().Format(time.RFC3339Nano)}})
	var s bson.M
	_ = a.db.Collection("samples").FindOne(r.Context(), bson.M{"sampleId": x["sampleId"]}).Decode(&s)
	if asString(s["currentHolderId"]) == actor.UserID {
		_, _ = a.db.Collection("samples").UpdateOne(r.Context(), bson.M{"sampleId": x["sampleId"]}, bson.M{"$set": bson.M{"latestLocation": coord, "locationRecordedAt": recorded.UTC().Format(time.RFC3339Nano)}})
	}
	out := bson.M{"assignmentId": x["assignmentId"], "coordinate": coord, "sequence": seq, "recordedAt": recorded.UTC().Format(time.RFC3339Nano)}
	a.audit(r.Context(), actor, "record_worker_location", "assignment", asString(x["assignmentId"]), true, out)
	return out, 201, nil
}

func (a *App) handleInitiateHandoff(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	if old, ok, e := a.idempotent(r.Context(), actor, "initiate_handoff", bson.M(body)); e != nil {
		return nil, 0, e
	} else if ok {
		return old, 201, nil
	}
	sampleID := asString(body["sampleId"])
	var s bson.M
	if a.db.Collection("samples").FindOne(r.Context(), bson.M{"sampleId": sampleID}).Decode(&s) != nil {
		return nil, 0, fail(404, "not_found", "Sample not found")
	}
	if asString(s["currentHolderId"]) != actor.UserID {
		return nil, 0, fail(409, "custody_required", "Only the current holder can initiate a handoff")
	}
	if asString(s["pendingHandoffId"]) != "" {
		return nil, 0, fail(409, "handoff_pending", "A handoff is already pending")
	}
	receiver := asString(body["receiverId"])
	var to bson.M
	if a.db.Collection("assignments").FindOne(r.Context(), bson.M{"assignmentId": asString(body["toAssignmentId"]), "workerId": receiver}).Decode(&to) != nil {
		return nil, 0, fail(409, "receiver_not_eligible", "Receiver is not assigned to the next work")
	}
	id := uuid()
	h := bson.M{"handoffId": id, "sampleId": sampleID, "fromAssignmentId": asString(body["fromAssignmentId"]), "toAssignmentId": asString(body["toAssignmentId"]), "senderId": actor.UserID, "receiverId": receiver, "senderConfirmed": false, "receiverConfirmed": false, "status": "pending", "initiatedAt": asString(body["initiatedAt"])}
	_, _ = a.db.Collection("handoffs").InsertOne(r.Context(), h)
	_, _ = a.db.Collection("samples").UpdateOne(r.Context(), bson.M{"sampleId": sampleID}, bson.M{"$set": bson.M{"pendingHandoffId": id}})
	out := bson.M{"handoffId": id, "senderId": actor.UserID, "receiverId": receiver, "currentHolderId": actor.UserID, "status": "pending"}
	a.saveIdempotent(r.Context(), actor, "initiate_handoff", bson.M(body), out)
	a.audit(r.Context(), actor, "initiate_handoff", "handoff", id, true, out)
	return out, 201, nil
}

func (a *App) handleConfirmHandoff(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	if old, ok, e := a.idempotent(r.Context(), actor, "confirm_handoff", bson.M(body)); e != nil {
		return nil, 0, e
	} else if ok {
		return old, 201, nil
	}
	id := asString(body["handoffId"])
	var h bson.M
	if a.db.Collection("handoffs").FindOne(r.Context(), bson.M{"handoffId": id}).Decode(&h) != nil {
		return nil, 0, fail(404, "not_found", "Handoff not found")
	}
	side := asString(body["confirmationSide"])
	expected := asString(h[side+"Id"])
	if expected == "" {
		if side == "sender" {
			expected = asString(h["senderId"])
		} else {
			expected = asString(h["receiverId"])
		}
	}
	if expected != actor.UserID {
		return nil, 0, fail(403, "forbidden", "Only the named party can confirm this side")
	}
	sender := asBool(h["senderConfirmed"])
	receiver := asBool(h["receiverConfirmed"])
	if side == "sender" {
		sender = true
	} else {
		receiver = true
	}
	status := "pending"
	holder := asString(h["senderId"])
	set := bson.M{side + "Confirmed": true}
	if sender && receiver {
		status = "confirmed"
		holder = asString(h["receiverId"])
		set["status"] = status
		set["completedAt"] = asString(body["confirmedAt"])
		_, _ = a.db.Collection("samples").UpdateOne(r.Context(), bson.M{"sampleId": h["sampleId"], "currentHolderId": h["senderId"]}, bson.M{"$set": bson.M{"currentHolderId": holder}, "$unset": bson.M{"pendingHandoffId": ""}})
	}
	_, _ = a.db.Collection("handoffs").UpdateOne(r.Context(), bson.M{"handoffId": id}, bson.M{"$set": set})
	entry := timelineEntry(actor, "handoff_"+status, "sample", asString(h["sampleId"]), bson.M{"handoffId": id, "currentHolderId": holder})
	a.appendTimeline(r.Context(), asString(h["sampleId"]), entry)
	out := bson.M{"handoffId": id, "status": status, "senderConfirmed": sender, "receiverConfirmed": receiver, "currentHolderId": holder}
	a.saveIdempotent(r.Context(), actor, "confirm_handoff", bson.M(body), out)
	a.audit(r.Context(), actor, "confirm_handoff", "handoff", id, true, out)
	return out, 201, nil
}

func (a *App) handleCheckpoint(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
