	if res, _ := a.db.Collection("samples").UpdateOne(r.Context(), bson.M{"sampleId": body["sampleId"]}, bson.M{"$set": bson.M{"status": "exception", "exception": ex}}); res.MatchedCount == 0 {
		return nil, 0, fail(404, "not_found", "Sample not found")
	}
	_, _ = a.db.Collection("exceptions").InsertOne(r.Context(), ex)
	entry := timelineEntry(actor, "laboratory_exception", "sample", asString(body["sampleId"]), ex)
	a.appendTimeline(r.Context(), asString(body["sampleId"]), entry)
	out := bson.M{"exceptionId": id, "sampleId": body["sampleId"], "status": "exception", "reason": body["reason"]}
	a.saveIdempotent(r.Context(), actor, "record_laboratory_exception", bson.M(body), out)
	a.audit(r.Context(), actor, "record_laboratory_exception", "sample", asString(body["sampleId"]), true, out)
