action.old_str:
import (
	"context"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo"
	"go.mongodb.org/mongo-driver/v2/mongo/options"
)

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	uri := os.Getenv("MONGODB_URI")
	if uri == "" {
		uri = "mongodb://127.0.0.1:27017/arena"
	}
	client, err := mongo.Connect(options.Client().ApplyURI(uri))
	if err != nil {
		log.Fatal(err)
	}
	if err := client.Ping(ctx, nil); err != nil {
		log.Fatal(err)
	}
	db := client.Database("lab_sample_delivery")
	app := NewApp(db, "/workspace/frontend/dist")
	if err := app.ensureFirstAdmin(ctx); err != nil {
		log.Fatal(err)
	}
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	server := &http.Server{Addr: "127.0.0.1:" + port, Handler: app, ReadHeaderTimeout: 10 * time.Second}
	log.Printf("LabLink listening at http://127.0.0.1:%s", port)
	if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatal(err)
	}
}

func (a *App) ensureFirstAdmin(ctx context.Context) error {
	count, err := a.db.Collection("users").CountDocuments(ctx, bson.M{})
	if err != nil || count != 0 {
		return err
	}
	username, password := os.Getenv("ADMIN_USERNAME"), os.Getenv("ADMIN_PASSWORD")
	if username == "" || password == "" {
		return nil
	}
	_, err = a.db.Collection("users").InsertOne(ctx, bson.M{
		"userId": uuid(), "username": username, "usernameLower": strings.ToLower(username),
		"passwordHash": passwordHash(username, password), "fullName": "System Administrator",
		"roles": bson.A{"administrator"}, "qualifications": bson.A{}, "certifications": bson.A{},
		"active": true, "available": true, "capacityUnits": 1, "assignmentCount": 0, "createdAt": now(),
	})
	return err
}

