export type Json = Record<string, any>;

const TOKEN_KEY = 'lablink.session';
export const session = {
  get: () => localStorage.getItem(TOKEN_KEY) || '',
  set: (token: string) => localStorage.setItem(TOKEN_KEY, token),
  clear: () => localStorage.removeItem(TOKEN_KEY),
};

export async function api<T = Json>(path: string, body?: Json, method = body === undefined ? 'GET' : 'POST'): Promise<T> {
  const headers: Record<string,string> = {Accept:'application/json'};
  if (body !== undefined) headers['Content-Type'] = 'application/json';
  if (session.get()) headers.Authorization = `Bearer ${session.get()}`;
  const response = await fetch(path, {method, headers, body: body === undefined ? undefined : JSON.stringify(body)});
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(payload.error || `Request failed (${response.status})`);
  return payload.data as T;
}

export const label = (value: string) => value.replaceAll('_',' ').replace(/\b\w/g, c => c.toUpperCase());
export const shortId = (value?: string) => value ? value.slice(0,8).toUpperCase() : '—';
export const when = (value?: string) => value ? new Date(value).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}) : '—';
export const idempotencyKey = () => crypto.randomUUID();

