import {useEffect, useRef} from 'react';
import maplibregl, {Map as MLMap, Marker} from 'maplibre-gl';
import {Protocol} from 'pmtiles';

type Point = {id?:string; name?:string; latitude:number; longitude:number; kind?:string; stale?:boolean};
const protocol = new Protocol();
let registered = false;

export default function NetworkMap({points=[]}:{points?:Point[]}) {
  const host = useRef<HTMLDivElement>(null);
  const map = useRef<MLMap|null>(null);
  useEffect(() => {
    if (!host.current || map.current) return;
    if (!registered) { maplibregl.addProtocol('pmtiles', protocol.tile); registered = true; }
    map.current = new maplibregl.Map({
      container: host.current,
      center:[77.5946,12.9716], zoom:10.5, attributionControl:false,
      style:{version:8,sources:{local:{type:'vector',url:'pmtiles:///maps/bangalore.pmtiles'}},layers:[
        {id:'bg',type:'background',paint:{'background-color':'#e8efe9'}},
        {id:'water',source:'local','source-layer':'water',type:'fill',paint:{'fill-color':'#9ed6da'}},
        {id:'land',source:'local','source-layer':'landuse',type:'fill',paint:{'fill-color':'#dce9d7','fill-opacity':.7}},
        {id:'roads',source:'local','source-layer':'roads',type:'line',paint:{'line-color':'#ffffff','line-width':['interpolate',['linear'],['zoom'],8,.4,15,3]}},
        {id:'road-outline',source:'local','source-layer':'roads',type:'line',paint:{'line-color':'#aebcb2','line-width':['interpolate',['linear'],['zoom'],8,.2,15,.7]}}
      ]}}
    });
    map.current.addControl(new maplibregl.NavigationControl({showCompass:false}),'bottom-right');
    map.current.addControl(new maplibregl.AttributionControl({compact:true}),'bottom-left');
    return () => { map.current?.remove(); map.current = null; };
  },[]);
  useEffect(() => {
    if (!map.current) return;
