   143				a.audit(r.Context(), actor, "permission_check", rt.operation, "", false, map[string]any{"code": e.Code})
   144				writeError(w, e)
   145				return
   146			}
   147		}
   148		data, status, e := rt.handler(w, r, actor, body)
   149		if e != nil {
   150			if actor != nil {
   151				a.audit(r.Context(), actor, rt.operation, "operation", "", false, map[string]any{"code": e.Code})
   152			}
   153			writeError(w, e)
   154			return
