   165			return nil, fail(400, "invalid_json", "Request body must be valid JSON")
   166		}
   167		if body == nil {
   168			return nil, fail(400, "invalid_json", "Request body must be an object")
   169		}
   170		if d.Decode(&struct{}{}) != io.EOF {
   171			return nil, fail(400, "invalid_json", "Request body must contain one JSON value")
