import {FormEvent, ReactNode, useCallback, useEffect, useMemo, useState} from 'react';
import NetworkMap from './NetworkMap';
import {api, idempotencyKey, label, session, shortId, when} from './api';

type User={userId:string;username:string;fullName:string;roles:string[];activeRole:string;roleSelectionRequired:boolean};
type Boot={user:User;serverTime:string;requesterSamples?:any[];operations?:any};
type Work={pending:any[];inProgress:any[];completed:any[]};
const roleNames:Record<string,string>={administrator:'Administrator',dispatcher:'Dispatcher',requester:'Requester',collection_professional:'Collection professional',delivery_partner:'Relay courier',node_handler:'Node handler',laboratory_team:'Laboratory intake'};
const icons:Record<string,string>={overview:'⌁',work:'▣',request:'＋',network:'◇',admin:'⚙',audit:'≡'};

function Login({onLogin}:{onLogin:()=>void}){
 const [username,setUsername]=useState(''); const [password,setPassword]=useState(''); const [busy,setBusy]=useState(false); const [error,setError]=useState('');
 async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{const x=await api<any>('/api/authenticate-user',{username,password});session.set(x.sessionToken);onLogin()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 return <main className="login-shell"><section className="login-story"><div className="brand light"><span className="brand-mark">L</span><span>LABLINK</span></div><div className="story-copy"><p className="eyebrow">Chain of custody, without compromise</p><h1>Every sample.<br/>Every handoff.<br/><em>Accounted for.</em></h1><p>A single operating picture for time-critical clinical logistics—from collection to laboratory receipt.</p></div><div className="route-art"><span>HOME</span><i/><b>COLLECTION</b><i/><b>HUB</b><i/><strong>LAB</strong></div></section><section className="login-panel"><form onSubmit={submit}><div className="mobile-brand brand"><span className="brand-mark">L</span> LABLINK</div><p className="eyebrow green">Secure operations portal</p><h2>Welcome back</h2><p className="muted">Sign in to continue under your assigned role.</p><label>Username<input autoFocus value={username} onChange={e=>setUsername(e.target.value)} placeholder="Enter your username" required/></label><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter your password" required/></label>{error&&<div className="alert error">{error}</div>}<button className="primary wide" disabled={busy}>{busy?'Signing in…':'Sign in securely'} <span>→</span></button><div className="security-note"><b>Encrypted & audited</b><small>Access and permission checks are logged.</small></div></form></section></main>
}

function RolePicker({user,onPick}:{user:User;onPick:(r:string)=>void}){return <div className="modal-backdrop"><section className="modal role-modal"><p className="eyebrow green">Active role</p><h2>Choose your workspace</h2><p className="muted">Your access and work queue will match this role. You can switch later.</p><div className="role-grid">{user.roles.map(r=><button key={r} onClick={()=>onPick(r)}><span>{r==='requester'?'◎':r.includes('collection')?'✣':r.includes('delivery')?'➜':r==='administrator'?'◆':'▦'}</span><b>{roleNames[r]||label(r)}</b><small>Open {roleNames[r]?.toLowerCase()} workspace</small></button>)}</div></section></div>}

function Stat({value,labelText,tone=''}:{value:any;labelText:string;tone?:string}){return <div className={`stat ${tone}`}><strong>{value??0}</strong><span>{labelText}</span></div>}
function Badge({status}:{status?:string}){return <span className={`badge ${(status||'unknown').replaceAll('_','-')}`}><i/>{label(status||'unknown')}</span>}
function Empty({text='No items here yet.'}:{text?:string}){return <div className="empty"><span>✓</span><b>All clear</b><p>{text}</p></div>}
function PageHead({eyebrow,title,children}:{eyebrow:string;title:string;children?:ReactNode}){return <header className="page-head"><div><p className="eyebrow green">{eyebrow}</p><h1>{title}</h1></div>{children}</header>}

function Overview({boot,onSample}:{boot:Boot;onSample:(id:string)=>void}){
 const ops=boot.operations||{}; const samples=boot.requesterSamples||ops.samples||[]; const exceptions=ops.exceptions||[];
 const points=useMemo(()=>[...(ops.locations||[]).map((x:any)=>({...x.coordinate,id:x.id,name:x.name,kind:'node'})),...(ops.workers||[]).map((x:any)=>({...x.latestLocation,id:x.workerId,name:x.fullName||'Worker',kind:'worker',stale:x.locationStale}))].filter(x=>Number.isFinite(x.latitude)),[ops]);
 return <><PageHead eyebrow="Live operations" title={boot.user.activeRole==='requester'?'Your sample journey':'Network command centre'}><span className="live"><i/> Live · updated {new Date(boot.serverTime).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</span></PageHead><div className="stats-row"><Stat value={samples.length} labelText="Samples in view"/><Stat value={(ops.routes||[]).length} labelText="Active journeys"/><Stat value={(ops.handoffs||[]).length} labelText="Open handoffs"/><Stat value={exceptions.length} labelText="Exceptions" tone={exceptions.length?'danger':''}/></div>{boot.user.activeRole!=='requester'&&<section className="map-card"><div className="card-title"><div><h2>Live network</h2><p>Locations, routes and field teams</p></div><div className="legend"><span><i className="node"/>Facility</span><span><i className="worker"/>Worker</span></div></div><NetworkMap points={points}/></section>}<section className="card"><div className="card-title"><div><h2>{boot.user.activeRole==='requester'?'Your samples':'Priority samples'}</h2><p>Current custody and delivery health</p></div></div>{samples.length?<div className="data-table"><div className="tr th"><span>Sample</span><span>Status</span><span>Deadline</span><span>Current holder</span><span>Location</span></div>{samples.slice(0,8).map((s:any)=><button className="tr" key={s.sampleId} onClick={()=>onSample(s.sampleId)}><span><b>#{shortId(s.sampleId)}</b><small>{shortId(s.requestId)}</small></span><span><Badge status={s.state?.status||s.status}/></span><span>{when(s.deliveryDeadline)}</span><span>{shortId(s.currentHolderId)}</span><span className={s.locationStale?'stale-text':''}>{s.locationStale?'● Stale':'● Current'}</span></button>)}</div>:<Empty text="No samples are currently visible in this role."/>}</section></>
}

function WorkView({role,notify,onSample}:{role:string;notify:(s:string,t?:boolean)=>void;onSample:(id:string)=>void}){
 const [work,setWork]=useState<Work>({pending:[],inProgress:[],completed:[]}); const [section,setSection]=useState<keyof Work>('pending'); const [loading,setLoading]=useState(true);
 const load=useCallback(()=>{setLoading(true);api<Work>('/api/list-role-work',{role}).then(setWork).catch(e=>notify(e.message,true)).finally(()=>setLoading(false))},[role,notify]); useEffect(load,[load]);
 async function action(path:string,item:any,extra:any={}){try{await api(path,{assignmentId:item.assignmentId,idempotencyKey:idempotencyKey(),...extra});notify('Work queue updated');load()}catch(e){notify((e as Error).message,true)}}
 function recordLocation(item:any){if(!navigator.geolocation){notify('Location services are unavailable',true);return}navigator.geolocation.getCurrentPosition(async p=>{try{await api('/api/record-worker-location',{assignmentId:item.assignmentId,coordinate:{latitude:p.coords.latitude,longitude:p.coords.longitude},sequence:Math.max(1,(item.history||[]).length+1),recordedAt:new Date().toISOString()});notify('Current location recorded');load()}catch(e){notify((e as Error).message,true)}},()=>notify('Allow location access to record your position',true),{enableHighAccuracy:true})}
 async function operationalAction(item:any){if(role==='collection_professional')return action('/api/collect-and-seal-sample',item,{sampleId:item.sampleId,collectedAt:new Date().toISOString(),containerType:'standard',observedTemperatureC:20});if(role==='laboratory_team'){try{await api('/api/confirm-laboratory-receipt',{sampleId:item.sampleId,laboratoryId:item.laboratoryId||item.nodeId,receivedAt:new Date().toISOString(),idempotencyKey:idempotencyKey()});notify('Laboratory receipt confirmed');load()}catch(e){notify((e as Error).message,true)}return}return action('/api/update-assignment-progress',item,{status:role==='delivery_partner'?'in_transit':'in_progress',occurredAt:new Date().toISOString()})}
 const items=work[section]||[];
 return <><PageHead eyebrow="Selected-role scope" title="My work"><button className="secondary" onClick={load}>↻ Refresh</button></PageHead><div className="tabs"><button className={section==='pending'?'active':''} onClick={()=>setSection('pending')}>Offers <b>{work.pending.length}</b></button><button className={section==='inProgress'?'active':''} onClick={()=>setSection('inProgress')}>In progress <b>{work.inProgress.length}</b></button><button className={section==='completed'?'active':''} onClick={()=>setSection('completed')}>Past work <b>{work.completed.length}</b></button></div><section className="work-list">{loading?<div className="loading">Loading work…</div>:items.length?items.map((x:any)=><article className="work-card" key={x.assignmentId||x.sampleId||x.journeyId}><div className="work-icon">{x.kind==='sample'?'◉':x.kind==='journey'?'⌁':'▣'}</div><div className="work-main"><div><span className="overline">{label(x.kind||'assignment')} · {shortId(x.assignmentId||x.journeyId||x.sampleId)}</span><h3>{x.fromLocationId&&x.toLocationId?`${shortId(x.fromLocationId)} → ${shortId(x.toLocationId)}`:`Sample #${shortId(x.sampleId)}`}</h3></div><div className="work-meta"><span><small>Status</small><Badge status={x.status}/></span>{x.offerExpiresAt&&<span><small>Offer expires</small>{when(x.offerExpiresAt)}</span>}{x.deliveryDeadline&&<span><small>Deadline</small>{when(x.deliveryDeadline)}</span>}<span><small>History</small>{(x.history||[]).length} updates</span></div></div><div className="work-actions">{section==='pending'&&x.assignmentId&&<><button className="primary" onClick={()=>action('/api/accept-assignment',x)}>Accept</button><button className="text-danger" onClick={()=>action('/api/decline-assignment',x,{reason:'Unable to accept',declinedAt:new Date().toISOString()})}>Decline</button></>}{section==='inProgress'&&x.assignmentId&&<><button className="primary" onClick={()=>operationalAction(x)}>{role==='collection_professional'?'Collect & seal':role==='laboratory_team'?'Confirm receipt':'Update progress'}</button><button className="secondary" onClick={()=>recordLocation(x)}>Record current location</button></>}{section!=='pending'&&x.sampleId&&<button className="secondary" onClick={()=>onSample(x.sampleId)}>View timeline</button>}</div></article>):<Empty text={`No ${section==='inProgress'?'active':section} work for this role.`}/>}</section></>
}

function RequestView({notify,onDone}:{notify:(s:string,t?:boolean)=>void;onDone:()=>void}){
 const initial={latitude:'12.9716',longitude:'77.5946',originType:'home',sampleTypeId:'10000000-0000-4000-8000-000000000001',containerType:'standard',earliestCollectionAt:'',latestCollectionAt:'',deliveryDeadline:''}; const [f,setF]=useState(initial); const [check,setCheck]=useState<any>(); const [busy,setBusy]=useState(false);
 const update=(k:string,v:string)=>setF({...f,[k]:v}); const payload=()=>({origin:{latitude:Number(f.latitude),longitude:Number(f.longitude)},originType:f.originType,sampleTypeId:f.sampleTypeId,requestedAt:new Date().toISOString(),earliestCollectionAt:new Date(f.earliestCollectionAt).toISOString(),latestCollectionAt:new Date(f.latestCollectionAt).toISOString(),deliveryDeadline:new Date(f.deliveryDeadline).toISOString()});
 async function service(e:FormEvent){e.preventDefault();setBusy(true);try{setCheck(await api('/api/check-serviceability',payload()));notify('Dry-run completed — no capacity reserved')}catch(e){notify((e as Error).message,true)}finally{setBusy(false)}}
 async function create(){setBusy(true);try{await api('/api/create-collection-request',{...payload(),containerType:f.containerType,temperatureMinC:2,temperatureMaxC:25,incompatibleSampleTypes:[],idempotencyKey:idempotencyKey()});notify('Collection request created');onDone()}catch(e){notify((e as Error).message,true)}finally{setBusy(false)}}
 return <><PageHead eyebrow="New request" title="Plan a sample collection"/><div className="form-layout"><form className="card form-card" onSubmit={service}><h2>Collection details</h2><p>Check the network first. This dry run creates no work or reservations.</p><div className="field-row"><label>Origin type<select value={f.originType} onChange={e=>update('originType',e.target.value)}><option value="home">Patient home</option><option value="clinic">Clinic</option><option value="node">Network node</option></select></label><label>Sample type<select value={f.sampleTypeId} onChange={e=>update('sampleTypeId',e.target.value)}><option value="amber">Amber</option><option value="indigo">Indigo</option><option value="frost">Frost</option><option value="pulse">Pulse</option></select></label></div><div className="field-row"><label>Latitude<input value={f.latitude} onChange={e=>update('latitude',e.target.value)} required/></label><label>Longitude<input value={f.longitude} onChange={e=>update('longitude',e.target.value)} required/></label></div><label>Earliest collection<input type="datetime-local" value={f.earliestCollectionAt} onChange={e=>update('earliestCollectionAt',e.target.value)} required/></label><label>Latest collection<input type="datetime-local" value={f.latestCollectionAt} onChange={e=>update('latestCollectionAt',e.target.value)} required/></label><label>Laboratory delivery deadline<input type="datetime-local" value={f.deliveryDeadline} onChange={e=>update('deliveryDeadline',e.target.value)} required/></label><button className="primary wide" disabled={busy}>Check serviceability →</button></form><aside className={`service-result ${check?'ready':''}`}><span className="result-symbol">{check?(check.serviceable?'✓':'!'):'⌁'}</span><h2>{check?(check.serviceable?'Route available':'Not serviceable'):'Ready to check'}</h2><p>{check?(check.reason||check.message||'Network, deadline, handling and capacity checks completed.'):'Enter the collection constraints to validate a route to an accepting laboratory.'}</p>{check&&<div className="result-facts"><span><small>Serviceability</small><b>{check.serviceable?'PASS':'REVIEW'}</b></span><span><small>Version</small><b>{check.serviceabilityVersion||check.version||'Current'}</b></span></div>}{check?.serviceable&&<button className="primary wide" type="button" onClick={create} disabled={busy}>Create collection request</button>}</aside></div></>
}

function NetworkView({ops}:{ops:any}){const locations=ops?.locations||[];const points=locations.map((x:any)=>({...x.coordinate,name:x.name,kind:'node'}));return <><PageHead eyebrow="Infrastructure" title="Network locations"/><section className="map-card network-large"><NetworkMap points={points}/></section><section className="card"><div className="data-table"><div className="tr th"><span>Location</span><span>Functions</span><span>Coverage</span><span>Regular capacity</span><span>Status</span></div>{locations.map((x:any)=><div className="tr" key={x.id}><span><b>{x.name}</b><small>#{shortId(x.id)}</small></span><span>{Object.entries(x.functions||{}).filter(([,v])=>v).map(([k])=>label(k)).join(', ')||'—'}</span><span>{x.coverageKm} km</span><span>{x.capacity?.availableUnits??'—'} available</span><span><Badge status={x.active?'active':'inactive'}/></span></div>)}</div></section></>}

function AdminView({notify}:{notify:(s:string,t?:boolean)=>void}){const [form,setForm]=useState({username:'',initialPassword:'',fullName:'',email:'',roles:['requester']});const set=(k:string,v:any)=>setForm({...form,[k]:v});async function submit(e:FormEvent){e.preventDefault();try{await api('/api/create-user',{...form,phone:'',qualifications:[],certifications:[],active:true});notify('User account created');setForm({...form,username:'',initialPassword:'',fullName:'',email:''})}catch(e){notify((e as Error).message,true)}}return <><PageHead eyebrow="Access management" title="People & permissions"/><div className="form-layout admin-layout"><section className="card admin-copy"><span className="big-symbol">◆</span><h2>Provision safely</h2><p>Accounts can hold multiple roles. Every action still runs only under the role the user explicitly selects.</p><ul><li>Professional certifications control collection eligibility</li><li>Facility teams are scoped to their assigned location</li><li>All permission checks are audited</li></ul></section><form className="card form-card" onSubmit={submit}><h2>Create user</h2><div className="field-row"><label>Full name<input value={form.fullName} onChange={e=>set('fullName',e.target.value)} required/></label><label>Email<input type="email" value={form.email} onChange={e=>set('email',e.target.value)} required/></label></div><div className="field-row"><label>Username<input value={form.username} onChange={e=>set('username',e.target.value)} required/></label><label>Temporary password<input type="password" value={form.initialPassword} onChange={e=>set('initialPassword',e.target.value)} required/></label></div><label>Initial role<select value={form.roles[0]} onChange={e=>set('roles',[e.target.value])}>{Object.entries(roleNames).map(([v,n])=><option key={v} value={v}>{n}</option>)}</select></label><button className="primary">Create account</button></form></div></>}

function AuditView({notify}:{notify:(s:string,t?:boolean)=>void}){const [q,setQ]=useState('');const [data,setData]=useState<any[]>([]);const search=useCallback(async()=>{try{const x=await api<any>('/api/search-audit-trail',{query:q,limit:100,offset:0,order:'newest_first'});setData(x.entries||[])}catch(e){notify((e as Error).message,true)}},[q,notify]);useEffect(()=>{search()},[]);return <><PageHead eyebrow="Accountability" title="Audit trail"><div className="search"><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search entity or action…"/><button onClick={search}>Search</button></div></PageHead><section className="timeline-list">{data.length?data.map(x=><article key={x.auditId}><i className={x.success?'ok':'bad'}/><div><div><b>{label(x.action)}</b><Badge status={x.success?'successful':'failed'}/></div><p>{label(x.entityType)} · {shortId(x.entityId)} · under {label(x.actorRole||x.role||'system')}</p><small>{when(x.occurredAt)}</small></div></article>):<Empty text="No audit entries match this search."/>}</section></>}

function SampleDrawer({id,onClose}:{id:string;onClose:()=>void}){const [x,setX]=useState<any>();useEffect(()=>{api('/api/read-sample-lifecycle',{sampleId:id}).then(setX)},[id]);return <div className="drawer-backdrop" onClick={onClose}><aside className="drawer" onClick={e=>e.stopPropagation()}><button className="drawer-close" onClick={onClose}>×</button><p className="eyebrow green">Lifecycle</p><h2>Sample #{shortId(id)}</h2>{!x?<div className="loading">Loading history…</div>:<><div className="drawer-status"><Badge status={x.status}/><span>{x.locationStale?'Location stale':'Location current'}</span></div>{x.exception&&<div className="exception-panel"><b>Exception flagged</b><p>{x.exception.message||x.exception.reason||label(x.exception.type||x.exception.code||'Handling requirements not met')}</p></div>}<dl><div><dt>Current holder</dt><dd>{shortId(x.currentHolderId)}</dd></div><div><dt>Journey</dt><dd>{shortId(x.activeJourneyId)}</dd></div><div><dt>Sealed</dt><dd>{x.sealed?'Yes':'No'}</dd></div></dl><h3>Status timeline</h3><div className="mini-timeline">{(x.timeline||[]).slice().reverse().map((t:any,i:number)=><div key={i}><i/><p><b>{label(t.status||t.action||'update')}</b><span>{when(t.occurredAt||t.at||t.timestamp)}</span></p></div>)}</div></>}</aside></div>}

export default function App(){const [boot,setBoot]=useState<Boot|null>(null);const [loading,setLoading]=useState(!!session.get());const [tab,setTab]=useState('overview');const [toast,setToast]=useState<{text:string;bad?:boolean}|null>(null);const [sample,setSample]=useState('');
 const notify=useCallback((text:string,bad=false)=>{setToast({text,bad});setTimeout(()=>setToast(null),4000)},[]); const load=useCallback(()=>{if(!session.get()){setLoading(false);return}setLoading(true);api<Boot>('/api/ui/bootstrap').then(setBoot).catch(()=>{session.clear();setBoot(null)}).finally(()=>setLoading(false))},[]);useEffect(load,[load]);
 useEffect(()=>{if(!boot?.user.activeRole)return;let cursor=0;const timer=setInterval(()=>api<any>(`/api/events?since=${cursor}`).then(x=>{cursor=x.cursor;if(x.events?.length)load()}).catch(()=>{}),8000);return()=>clearInterval(timer)},[boot?.user.activeRole,load]);
 async function chooseRole(role:string){try{await api('/api/select-active-role',{role});setTab('overview');load()}catch(e){notify((e as Error).message,true)}} function logout(){session.clear();setBoot(null)}
 if(loading&&!boot)return <div className="splash"><span className="brand-mark">L</span><p>Securing your workspace…</p></div>;if(!boot)return <Login onLogin={load}/>;
 const role=boot.user.activeRole; const nav=[['overview','Overview'],['work','My work'],...(role==='requester'?[['request','New request']]:[]),...(['administrator','dispatcher','node_handler','laboratory_team'].includes(role)?[['network','Network']]:[]),...(role==='administrator'?[['admin','Administration'],['audit','Audit trail']]:role==='dispatcher'?[['audit','Audit trail']]:[])];
 return <div className="app-shell"><aside className="sidebar"><div className="brand light"><span className="brand-mark">L</span><span>LABLINK</span></div><div className="role-context"><small>Working as</small><button onClick={()=>setBoot({...boot,user:{...boot.user,roleSelectionRequired:true}})}><b>{roleNames[role]||label(role)}</b><span>⌄</span></button></div><nav>{nav.map(([id,name])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}><span>{icons[id]}</span>{name}</button>)}</nav><div className="side-bottom"><div className="avatar">{(boot.user.fullName||boot.user.username).slice(0,2).toUpperCase()}</div><div><b>{boot.user.fullName||boot.user.username}</b><small>{roleNames[role]}</small></div><button title="Sign out" onClick={logout}>↪</button></div></aside><main className="workspace"><div className="mobile-top"><div className="brand"><span className="brand-mark">L</span> LABLINK</div><select value={tab} onChange={e=>setTab(e.target.value)}>{nav.map(([id,n])=><option value={id}>{n}</option>)}</select></div>{tab==='overview'&&<Overview boot={boot} onSample={setSample}/>} {tab==='work'&&<WorkView role={role} notify={notify} onSample={setSample}/>} {tab==='request'&&<RequestView notify={notify} onDone={()=>{setTab('overview');load()}}/>} {tab==='network'&&<NetworkView ops={boot.operations}/>} {tab==='admin'&&<AdminView notify={notify}/>} {tab==='audit'&&<AuditView notify={notify}/>}</main>{boot.user.roleSelectionRequired&&<RolePicker user={boot.user} onPick={chooseRole}/>} {sample&&<SampleDrawer id={sample} onClose={()=>setSample('')}/>} {toast&&<div className={`toast ${toast.bad?'bad':''}`}>{toast.bad?'!':'✓'} {toast.text}</div>}</div>}

