		}
		samples = append(samples, x)
	}
	workers := bson.A{}
	counts := []int{}
	for _, u := range a.findAll(ctx, "users", bson.M{"roles": bson.M{"$in": bson.A{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"}}}) {
		count := asInt(u["assignmentCount"])
		counts = append(counts, count)
		x := bson.M{"workerId": asString(u["userId"]), "fullName": asString(u["fullName"]), "roles": stringSlice(u["roles"]), "available": asBool(u["available"]), "status": map[bool]string{true: "available", false: "unavailable"}[asBool(u["available"])], "capacityUnits": asInt(u["capacityUnits"]), "assignmentCount": count, "locationStale": stale(u["locationRecordedAt"])}
		if c := coordinate(u["latestLocation"]); len(c) > 0 {
			x["latestLocation"] = c
		}
		if t := asString(u["locationRecordedAt"]); t != "" {
			x["locationRecordedAt"] = t
		}
		workers = append(workers, x)
	}
	locations := bson.A{}
	lf := bson.M{}
	if locationOnly != "" {
		lf["locationId"] = locationOnly
	}
	for _, l := range a.findAll(ctx, "locations", lf) {
		x := operationsLocation(l)
		acc := a.findAll(ctx, "capacities", bson.M{"kind": "laboratory_acceptance", "resourceId": l["locationId"], "accepts": true})
		ids := bson.A{}
		for _, v := range acc {
			ids = append(ids, v["sampleTypeId"])
		}
		if len(ids) > 0 {
			x["acceptedSampleTypeIds"] = ids
		}
		locations = append(locations, x)
	}
	connections := bson.A{}
	if locationOnly == "" {
		for _, c := range a.findAll(ctx, "connections", bson.M{}) {
			connections = append(connections, operationsConnection(c))
		}
	}
	routes := bson.A{}
	for _, j := range a.findAll(ctx, "journeys", bson.M{}) {
		routes = append(routes, journeyDTO(j))
	}
	handoffs := bson.A{}
	for _, h := range a.findAll(ctx, "handoffs", bson.M{"status": "pending"}) {
		delete(h, "_id")
		handoffs = append(handoffs, h)
	}
	exceptions := bson.A{}
	for _, x := range a.findAll(ctx, "exceptions", bson.M{}) {
		delete(x, "_id")
		exceptions = append(exceptions, x)
	}
	spread := 0
	if len(counts) > 0 {
		sort.Ints(counts)
		spread = counts[len(counts)-1] - counts[0]
	}
	unassigned, _ := a.db.Collection("assignments").CountDocuments(ctx, bson.M{"status": "unassigned"})
	return bson.M{"samples": samples, "workers": workers, "locations": locations, "connections": connections, "routes": routes, "handoffs": handoffs, "delays": bson.A{}, "exceptions": exceptions, "assignmentCountSpread": spread, "ineligibleAssignmentCount": int(unassigned)}
}

