package main

import (
	"net/http"
	"strings"
	"time"

	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo"
	"go.mongodb.org/mongo-driver/v2/mongo/options"
)

func (a *App) handleLogin(_ http.ResponseWriter, r *http.Request, _ *Actor, body bsonMap) (any, int, *apiError) {
	username, password := asString(body["username"]), asString(body["password"])
	var u bson.M
	if a.db.Collection("users").FindOne(r.Context(), bson.M{"usernameLower": strings.ToLower(username), "active": true}).Decode(&u) != nil || asString(u["passwordHash"]) != passwordHash(username, password) {
		a.audit(r.Context(), nil, "sign_in", "user", username, false, bson.M{"reason": "invalid_credentials"})
		return nil, 0, fail(401, "invalid_credentials", "Invalid username or password")
	}
	roles := stringSlice(u["roles"])
	active := ""
	if len(roles) == 1 {
		active = roles[0]
	}
	t := token()
	_, e := a.db.Collection("sessions").InsertOne(r.Context(), bson.M{"token": t, "userId": asString(u["userId"]), "activeRole": active, "createdAt": now(), "expiresAt": time.Now().UTC().Add(24 * time.Hour).Format(time.RFC3339Nano)})
	if e != nil {
		return nil, 0, fail(500, "internal_error", "Could not create session")
	}
	actor := &Actor{UserID: asString(u["userId"]), Roles: roles, ActiveRole: active}
	a.audit(r.Context(), actor, "sign_in", "user", actor.UserID, true, bson.M{})
	return bson.M{"sessionToken": t, "userId": actor.UserID, "roles": roles, "activeRole": active}, 200, nil
}

func (a *App) handleSelectRole(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	role := asString(body["role"])
	if !validRoles[role] || !contains(actor.Roles, role) {
		return nil, 0, fail(403, "forbidden", "Role is not assigned to this user")
	}
	_, e := a.db.Collection("sessions").UpdateOne(r.Context(), bson.M{"token": actor.SessionToken}, bson.M{"$set": bson.M{"activeRole": role}})
	if e != nil {
		return nil, 0, fail(500, "internal_error", "Could not select role")
	}
	actor.ActiveRole = role
	a.audit(r.Context(), actor, "select_active_role", "session", actor.UserID, true, bson.M{"role": role})
	return bson.M{"activeRole": role, "roles": actor.Roles}, 200, nil
}

func (a *App) handleCreateUser(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	roles := stringsFromAny(body["roles"])
	for _, role := range roles {
		if !validRoles[role] {
			return nil, 0, fail(400, "invalid_json", "Unknown role")
		}
	}
	if (contains(roles, "node_handler") || contains(roles, "laboratory_team")) && asString(body["assignedLocationId"]) == "" {
		return nil, 0, fail(400, "invalid_assignment", "Assigned location is required")
	}
	u := bson.M{"userId": uuid(), "username": asString(body["username"]), "usernameLower": strings.ToLower(asString(body["username"])), "passwordHash": passwordHash(asString(body["username"]), asString(body["initialPassword"])), "email": asString(body["email"]), "fullName": asString(body["fullName"]), "phone": asString(body["phone"]), "roles": roles, "qualifications": stringsFromAny(body["qualifications"]), "certifications": normalCertifications(body["certifications"]), "active": asBool(body["active"]), "available": true, "capacityUnits": 1, "assignmentCount": 0, "assignedLocationId": asString(body["assignedLocationId"]), "createdAt": now()}
	_, e := a.db.Collection("users").InsertOne(r.Context(), u)
	if mongo.IsDuplicateKeyError(e) {
		return nil, 0, fail(409, "duplicate_username", "Username already exists")
	}
	if e != nil {
		return nil, 0, fail(500, "internal_error", "Could not create user")
	}
	a.audit(r.Context(), actor, "create_user", "user", asString(u["userId"]), true, bson.M{"roles": roles})
	return publicUser(u), 201, nil
}

func (a *App) handleUpdateUser(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	id := asString(body["userId"])
	roles := stringsFromAny(body["roles"])
	for _, role := range roles {
		if !validRoles[role] {
			return nil, 0, fail(400, "invalid_json", "Unknown role")
		}
	}
	set := bson.M{"roles": roles, "active": asBool(body["active"])}
	if _, ok := body["qualifications"]; ok {
		set["qualifications"] = stringsFromAny(body["qualifications"])
	}
	if _, ok := body["certifications"]; ok {
		set["certifications"] = normalCertifications(body["certifications"])
	}
	if _, ok := body["assignedLocationId"]; ok {
		set["assignedLocationId"] = asString(body["assignedLocationId"])
	}
	res, e := a.db.Collection("users").UpdateOne(r.Context(), bson.M{"userId": id}, bson.M{"$set": set})
	if e != nil {
		return nil, 0, fail(500, "internal_error", "Could not update user")
	}
	if res.MatchedCount == 0 {
		return nil, 0, fail(404, "not_found", "User not found")
	}
	var u bson.M
	_ = a.db.Collection("users").FindOne(r.Context(), bson.M{"userId": id}).Decode(&u)
	a.audit(r.Context(), actor, "update_user_access", "user", id, true, set)
	return bson.M{"userId": id, "roles": stringSlice(u["roles"]), "qualifications": stringSlice(u["qualifications"]), "certifications": orArray(u["certifications"]), "active": asBool(u["active"])}, 201, nil
}

func normalCertifications(v any) bson.A {
	out := bson.A{}
	var values []any
	switch a := v.(type) {
	case []any:
		values = a
	case bson.A:
		values = []any(a)
	}
	for _, x := range values {
		m := toBson(x)
		if asString(m["code"]) == "" {
			continue
		}
		if _, ok := m["active"]; !ok {
			m["active"] = true
		}
		out = append(out, m)
	}
	return out
}

func stringsFromAny(v any) []string {
	out := []string{}
	switch a := v.(type) {
	case []any:
		for _, x := range a {
			out = append(out, asString(x))
		}
	case bson.A:
		for _, x := range a {
			out = append(out, asString(x))
		}
	case []string:
		return a
	}
	return out
}

func toBson(v any) bson.M {
	switch x := v.(type) {
	case bson.M:
		return x
	case map[string]any:
		return bson.M(x)
	case bsonMap:
		return bson.M(x)
	}
	return bson.M{}
}

func (a *App) handleCreateSampleType(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	if asFloat(body["temperatureMinC"]) > asFloat(body["temperatureMaxC"]) {
		return nil, 0, fail(400, "invalid_handling_rule", "Minimum temperature exceeds maximum")
	}
	name := asString(body["name"])
	qualified := true
	if v, ok := body["qualifiedCollectorRequired"]; ok {
		qualified = asBool(v)
	}
	required := asString(body["requiredQualification"])
	if required == "" && qualified {
		required = name
	}
	s := bson.M{"sampleTypeId": uuid(), "name": name, "qualifiedCollectorRequired": qualified, "requiredQualification": required, "containerType": asString(body["containerType"]), "temperatureMinC": asFloat(body["temperatureMinC"]), "temperatureMaxC": asFloat(body["temperatureMaxC"]), "incompatibleSampleTypes": stringsFromAny(body["incompatibleSampleTypes"]), "requiresCooledRoute": asBool(body["requiresCooledRoute"]), "batchingAllowed": true, "active": true}
	if v, ok := body["batchingAllowed"]; ok {
		s["batchingAllowed"] = asBool(v)
	}
	_, e := a.db.Collection("sample_types").InsertOne(r.Context(), s)
	if mongo.IsDuplicateKeyError(e) {
		return nil, 0, fail(409, "duplicate_sample_type", "Sample type already exists")
	}
	if e != nil {
		return nil, 0, fail(500, "internal_error", "Could not create sample type")
	}
	a.bumpNetwork(r.Context())
	a.audit(r.Context(), actor, "create_sample_type", "sample_type", asString(s["sampleTypeId"]), true, sampleTypeDTO(s))
	return sampleTypeDTO(s), 201, nil
}

func (a *App) handleUpdateSampleType(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	if asFloat(body["temperatureMinC"]) > asFloat(body["temperatureMaxC"]) {
		return nil, 0, fail(400, "invalid_handling_rule", "Minimum temperature exceeds maximum")
	}
	id := asString(body["sampleTypeId"])
	set := bson.M{"containerType": asString(body["containerType"]), "temperatureMinC": asFloat(body["temperatureMinC"]), "temperatureMaxC": asFloat(body["temperatureMaxC"])}
	for _, k := range []string{"qualifiedCollectorRequired", "requiredQualification", "requiresCooledRoute", "batchingAllowed"} {
		if v, ok := body[k]; ok {
			set[k] = v
		}
	}
	if _, ok := body["incompatibleSampleTypes"]; ok {
		set["incompatibleSampleTypes"] = stringsFromAny(body["incompatibleSampleTypes"])
	}
	res, _ := a.db.Collection("sample_types").UpdateOne(r.Context(), bson.M{"sampleTypeId": id}, bson.M{"$set": set})
	if res.MatchedCount == 0 {
		return nil, 0, fail(404, "not_found", "Sample type not found")
	}
	var s bson.M
	_ = a.db.Collection("sample_types").FindOne(r.Context(), bson.M{"sampleTypeId": id}).Decode(&s)
	a.bumpNetwork(r.Context())
	a.audit(r.Context(), actor, "update_sample_type", "sample_type", id, true, set)
	return sampleTypeDTO(s), 201, nil
}

func validateCoord(v any) *apiError {
	c := toBson(v)
	lat, lon := asFloat(c["latitude"]), asFloat(c["longitude"])
	if lat < -90 || lat > 90 || lon < -180 || lon > 180 {
		return fail(400, "invalid_coordinate", "Coordinate is outside valid bounds")
	}
	return nil
}
func (a *App) handleCreateLocation(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	if e := validateCoord(body["coordinate"]); e != nil {
		return nil, 0, e
	}
	coverage := 5.0
	if _, ok := body["coverageKm"]; ok {
		coverage = asFloat(body["coverageKm"])
	}
	if coverage <= 0 || coverage > 5 {
		return nil, 0, fail(400, "invalid_node_coverage", "Coverage must be within 5 km")
	}
	handling := asInt(body["handlingMinutes"])
	if handling < 0 || handling > 1440 {
		return nil, 0, fail(400, "invalid_handling_time", "Invalid handling time")
	}
	functions := stringsFromAny(body["functions"])
	if len(functions) == 0 {
		return nil, 0, fail(400, "invalid_location_function", "At least one function is required")
	}
	cap := bson.M{"capacityUnits": 0, "reservedUnits": 0, "availableUnits": 0, "cooledCapacityUnits": 0, "cooledReservedUnits": 0, "cooledAvailableUnits": 0}
	l := bson.M{"locationId": uuid(), "name": asString(body["name"]), "coordinate": toBson(body["coordinate"]), "coverageKm": coverage, "handlingMinutes": handling, "active": asBool(body["active"]), "functions": functionStates(functions), "capacity": cap, "createdAt": now()}
	_, e := a.db.Collection("locations").InsertOne(r.Context(), l)
	if e != nil {
		return nil, 0, fail(500, "internal_error", "Could not create location")
	}
	a.bumpNetwork(r.Context())
	a.audit(r.Context(), actor, "create_location", "location", asString(l["locationId"]), true, locationDTO(l))
	return locationDTO(l), 201, nil
}

func (a *App) handleUpdateLocation(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	if e := validateCoord(body["coordinate"]); e != nil {
		return nil, 0, e
	}
	id := asString(body["locationId"])
	set := bson.M{"name": asString(body["name"]), "coordinate": toBson(body["coordinate"])}
	if _, ok := body["coverageKm"]; ok {
		v := asFloat(body["coverageKm"])
		if v <= 0 || v > 5 {
			return nil, 0, fail(400, "invalid_node_coverage", "Coverage must be within 5 km")
		}
		set["coverageKm"] = v
	}
	if _, ok := body["handlingMinutes"]; ok {
		set["handlingMinutes"] = asInt(body["handlingMinutes"])
	}
	if _, ok := body["functions"]; ok {
		set["functions"] = functionStates(stringsFromAny(body["functions"]))
	}
	res, _ := a.db.Collection("locations").UpdateOne(r.Context(), bson.M{"locationId": id}, bson.M{"$set": set})
	if res.MatchedCount == 0 {
		return nil, 0, fail(404, "not_found", "Location not found")
	}
	var l bson.M
	_ = a.db.Collection("locations").FindOne(r.Context(), bson.M{"locationId": id}).Decode(&l)
	a.bumpNetwork(r.Context())
	a.audit(r.Context(), actor, "update_location", "location", id, true, set)
	return locationDTO(l), 201, nil
}

func (a *App) handleLocationStatus(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	id := asString(body["locationId"])
	res, _ := a.db.Collection("locations").UpdateOne(r.Context(), bson.M{"locationId": id}, bson.M{"$set": bson.M{"active": asBool(body["active"])}})
	if res.MatchedCount == 0 {
		return nil, 0, fail(404, "not_found", "Location not found")
	}
	a.bumpNetwork(r.Context())
	a.audit(r.Context(), actor, "set_location_status", "location", id, true, body)
	return bson.M{"locationId": id, "active": asBool(body["active"])}, 200, nil
}
func (a *App) handleFunctionStatus(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	id, fn := asString(body["locationId"]), asString(body["function"])
	if fn != "collection_point" && fn != "transfer_point" && fn != "hub" && fn != "laboratory" {
		return nil, 0, fail(400, "invalid_location_function", "Invalid function")
	}
	res, _ := a.db.Collection("locations").UpdateOne(r.Context(), bson.M{"locationId": id}, bson.M{"$set": bson.M{"functions." + fn: asBool(body["active"])}})
	if res.MatchedCount == 0 {
		return nil, 0, fail(404, "not_found", "Location not found")
	}
	var l bson.M
	_ = a.db.Collection("locations").FindOne(r.Context(), bson.M{"locationId": id}).Decode(&l)
	a.bumpNetwork(r.Context())
	a.audit(r.Context(), actor, "set_location_function_status", "location", id, true, body)
	return bson.M{"locationId": id, "function": fn, "active": asBool(body["active"]), "functions": coordinate(l["functions"])}, 200, nil
}

func (a *App) handleCreateConnection(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	from, to := asString(body["fromLocationId"]), asString(body["toLocationId"])
	if from == to {
		return nil, 0, fail(400, "invalid_connection", "Connection endpoints must differ")
	}
	for _, id := range []string{from, to} {
		if a.db.Collection("locations").FindOne(r.Context(), bson.M{"locationId": id}).Err() != nil {
			return nil, 0, fail(404, "not_found", "Location not found")
		}
	}
	travel := asInt(body["travelMinutes"])
	if travel <= 0 {
		return nil, 0, fail(400, "invalid_travel_time", "Travel time must be positive")
	}
	cooled := asBool(body["cooled"])
	cap := bson.M{"capacityUnits": 0, "reservedUnits": 0, "availableUnits": 0, "cooledCapacityUnits": 0, "cooledReservedUnits": 0, "cooledAvailableUnits": 0}
	c := bson.M{"connectionId": uuid(), "fromLocationId": from, "toLocationId": to, "travelMinutes": travel, "costUnits": asFloat(body["costUnits"]), "cooled": cooled, "active": asBool(body["active"]), "capacity": cap}
	_, e := a.db.Collection("connections").InsertOne(r.Context(), c)
	if e != nil {
		return nil, 0, fail(500, "internal_error", "Could not create connection")
	}
	a.bumpNetwork(r.Context())
	a.audit(r.Context(), actor, "create_connection", "connection", asString(c["connectionId"]), true, c)
	return bson.M{"connectionId": c["connectionId"], "fromLocationId": from, "toLocationId": to, "travelMinutes": travel, "costUnits": c["costUnits"], "cooled": cooled, "active": c["active"]}, 201, nil
}
func (a *App) handleConnectionStatus(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	id := asString(body["connectionId"])
