	if lat < -90 || lat > 90 || lon < -180 || lon > 180 {
		return fail(400, "invalid_coordinate", "Coordinate is outside valid bounds")
	}
	return nil
}
func (a *App) handleCreateLocation(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
