func (a *App) handleCapacity(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	id := asString(body["resourceId"])
	regular, cooled := asInt(body["capacityUnits"]), asInt(body["cooledCapacityUnits"])
	if regular < 0 || cooled < 0 {
		return nil, 0, fail(400, "invalid_capacity", "Capacity cannot be negative")
	}
	if actor.ActiveRole != "administrator" {
		if actor.AssignedLocationID != id {
			return nil, 0, fail(403, "wrong_location", "Capacity is limited to the assigned location")
		}
	}
	for _, name := range []string{"locations", "connections"} {
		var d bson.M
		if a.db.Collection(name).FindOne(r.Context(), bson.M{name[:len(name)-1] + "Id": id}).Decode(&d) == nil {
			old := capacityOf(d)
			if regular < asInt(old["reservedUnits"]) || cooled < asInt(old["cooledReservedUnits"]) {
				return nil, 0, fail(409, "capacity_below_reserved", "Configured capacity is below reserved capacity")
			}
			cap := bson.M{"capacityUnits": regular, "reservedUnits": asInt(old["reservedUnits"]), "availableUnits": regular - asInt(old["reservedUnits"]), "cooledCapacityUnits": cooled, "cooledReservedUnits": asInt(old["cooledReservedUnits"]), "cooledAvailableUnits": cooled - asInt(old["cooledReservedUnits"])}
			_, _ = a.db.Collection(name).UpdateOne(r.Context(), bson.M{name[:len(name)-1] + "Id": id}, bson.M{"$set": bson.M{"capacity": cap}})
			_, _ = a.db.Collection("capacities").UpdateOne(r.Context(), bson.M{"resourceId": id, "kind": "capacity"}, bson.M{"$set": bson.M{"capacity": cap}}, options.UpdateOne().SetUpsert(true))
			a.bumpNetwork(r.Context())
			a.audit(r.Context(), actor, "configure_capacity", "capacity", id, true, cap)
			return bson.M{"resourceId": id, "capacityUnits": regular, "cooledCapacityUnits": cooled}, 200, nil
		}
	}
	return nil, 0, fail(404, "not_found", "Capacity resource not found")
}

func (a *App) handleLabAcceptance(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	lab, st := asString(body["laboratoryId"]), asString(body["sampleTypeId"])
	var l bson.M
	if a.db.Collection("locations").FindOne(r.Context(), bson.M{"locationId": lab, "functions.laboratory": true}).Decode(&l) != nil {
		return nil, 0, fail(404, "not_found", "Laboratory not found")
	}
	if a.db.Collection("sample_types").FindOne(r.Context(), bson.M{"sampleTypeId": st}).Err() != nil {
		return nil, 0, fail(404, "not_found", "Sample type not found")
	}
	var old bson.M
	_ = a.db.Collection("capacities").FindOne(r.Context(), bson.M{"resourceId": lab, "sampleTypeId": st, "kind": "laboratory_acceptance"}).Decode(&old)
	id := asString(old["acceptanceId"])
	if id == "" {
		id = uuid()
	}
	_, _ = a.db.Collection("capacities").UpdateOne(r.Context(), bson.M{"resourceId": lab, "sampleTypeId": st, "kind": "laboratory_acceptance"}, bson.M{"$set": bson.M{"acceptanceId": id, "accepts": asBool(body["accepts"])}}, options.UpdateOne().SetUpsert(true))
	a.bumpNetwork(r.Context())
	a.audit(r.Context(), actor, "configure_laboratory_acceptance", "laboratory", lab, true, body)
	return bson.M{"acceptanceId": id, "accepts": asBool(body["accepts"])}, 200, nil
}

func (a *App) handleWorkerAvailability(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	id := asString(body["workerId"])
	if actor.ActiveRole != "administrator" && actor.ActiveRole != "dispatcher" && id != actor.UserID {
		return nil, 0, fail(403, "forbidden", "Workers may update only their own availability")
	}
	cap := asInt(body["capacityUnits"])
	if cap < 0 {
		return nil, 0, fail(400, "invalid_capacity", "Capacity cannot be negative")
	}
	res, _ := a.db.Collection("users").UpdateOne(r.Context(), bson.M{"userId": id}, bson.M{"$set": bson.M{"available": asBool(body["available"]), "capacityUnits": cap}})
	if res.MatchedCount == 0 {
