}

func normalCertifications(v any) bson.A {
	out := bson.A{}
	var values []any
	switch a := v.(type) {
	case []any:
		values = a
	case bson.A:
		values = []any(a)
	}
	for _, x := range values {
		m := toBson(x)
		if asString(m["code"]) == "" {
			continue
		}
		if _, ok := m["active"]; !ok {
			m["active"] = true
		}
		out = append(out, m)
	}
	return out
}

func stringsFromAny(v any) []string {
	out := []string{}
	switch a := v.(type) {
	case []any:
		for _, x := range a {
			out = append(out, asString(x))
		}
	case bson.A:
		for _, x := range a {
			out = append(out, asString(x))
		}
	case []string:
		return a
	}
	return out
}

func toBson(v any) bson.M {
	switch x := v.(type) {
	case bson.M:
		return x
	case bson.D:
		out := bson.M{}
		for _, element := range x {
			out[element.Key] = element.Value
		}
		return out
	case map[string]any:
		return bson.M(x)
	case bsonMap:
		return bson.M(x)
	}
	return bson.M{}
}

func (a *App) handleCreateSampleType(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	if asFloat(body["temperatureMinC"]) > asFloat(body["temperatureMaxC"]) {
		return nil, 0, fail(400, "invalid_handling_rule", "Minimum temperature exceeds maximum")
	}
