package main

import (
	"context"
	"net/http"
	"sort"
	"strconv"
	"strings"

	"go.mongodb.org/mongo-driver/v2/bson"
	"go.mongodb.org/mongo-driver/v2/mongo/options"
)

func (a *App) canReadSample(ctx context.Context, actor *Actor, s bson.M) bool {
	if actor.ActiveRole == "administrator" || actor.ActiveRole == "dispatcher" {
		return true
	}
	if actor.ActiveRole == "requester" {
		return asString(s["requesterId"]) == actor.UserID
	}
	return a.db.Collection("assignments").FindOne(ctx, bson.M{"sampleId": s["sampleId"], "workerId": actor.UserID, "requiredRole": actor.ActiveRole}).Err() == nil
}

func (a *App) handleSampleStateHTTP(w http.ResponseWriter, r *http.Request, id string) {
	if r.Method != "GET" {
		writeError(w, fail(405, "method_not_allowed", "Method not allowed"))
		return
	}
	actor, e := a.authenticate(r)
	if e != nil {
		writeError(w, e)
		return
	}
	if e = a.authorize(actor, "read_sample_state"); e != nil {
		writeError(w, e)
		return
	}
	var s bson.M
	if a.db.Collection("samples").FindOne(r.Context(), bson.M{"sampleId": id}).Decode(&s) != nil {
		writeError(w, fail(404, "not_found", "Sample not found"))
		return
	}
	if !a.canReadSample(r.Context(), actor, s) {
		writeError(w, fail(403, "forbidden", "Sample is outside selected-role scope"))
		return
	}
	writeJSON(w, 200, bson.M{"data": sampleStateDTO(s)})
}

func sampleStateDTO(s bson.M) bson.M {
	out := bson.M{"sampleId": asString(s["sampleId"]), "requestId": asString(s["requestId"]), "requesterId": asString(s["requesterId"]), "origin": coordinate(s["origin"]), "originType": asString(s["originType"]), "requestedAt": asString(s["requestedAt"]), "deliveryDeadline": asString(s["deliveryDeadline"]), "sampleTypeId": asString(s["sampleTypeId"]), "containerType": asString(s["containerType"]), "temperatureMinC": asFloat(s["temperatureMinC"]), "temperatureMaxC": asFloat(s["temperatureMaxC"]), "incompatibleSampleTypes": orArray(s["incompatibleSampleTypes"]), "serviceability": asString(s["serviceability"]), "activeAssignmentIds": orArray(s["activeAssignmentIds"]), "state": bson.M{"status": asString(s["status"])}, "timeline": orArray(s["timeline"]), "locationStale": stale(s["locationRecordedAt"])}
	for _, k := range []string{"activeJourneyId", "targetLaboratoryId", "locationRecordedAt"} {
		if v := asString(s[k]); v != "" {
			out[k] = v
		}
	}
	if c := coordinate(s["latestLocation"]); len(c) > 0 {
		out["latestLocation"] = c
	}
	return out
}

func (a *App) handleLifecycle(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	var s bson.M
	if a.db.Collection("samples").FindOne(r.Context(), bson.M{"sampleId": asString(body["sampleId"])}).Decode(&s) != nil {
		return nil, 0, fail(404, "not_found", "Sample not found")
	}
	if !a.canReadSample(r.Context(), actor, s) {
		return nil, 0, fail(403, "forbidden", "Sample is outside selected-role scope")
	}
	return a.lifecycleDTO(r, s), 200, nil
}
func (a *App) lifecycleDTO(r *http.Request, s bson.M) bson.M {
	out := bson.M{"sampleId": asString(s["sampleId"]), "status": asString(s["status"]), "sealed": asBool(s["sealed"]), "completedLegIds": orArray(s["completedLegIds"]), "activeReplacementPlanIds": orArray(s["activeReplacementPlanIds"]), "timeline": orArray(s["timeline"]), "locationStale": stale(s["locationRecordedAt"])}
	for _, k := range []string{"activeJourneyId", "currentHolderId", "receivedLaboratoryId", "pendingHandoffId", "locationRecordedAt"} {
		if v := asString(s[k]); v != "" {
			out[k] = v
		}
	}
	if x := toBson(s["exception"]); len(x) > 0 {
		out["exception"] = x
	}
	if c := coordinate(s["latestLocation"]); len(c) > 0 {
		out["latestLocation"] = c
	}
	if id := asString(s["pendingHandoffId"]); id != "" {
		var h bson.M
		if a.db.Collection("handoffs").FindOne(r.Context(), bson.M{"handoffId": id}).Decode(&h) == nil {
			delete(h, "_id")
			out["pendingHandoff"] = h
		}
	}
	return out
}

func journeyStops(value any) bson.A {
	values, ok := value.(bson.A)
	if !ok {
		return bson.A{}
	}
	out := bson.A{}
	for _, value := range values {
		stop := toBson(value)
		switch asString(stop["stopType"]) {
		case "collection":
			stop["stopType"] = "pickup"
		case "laboratory":
			stop["stopType"] = "delivery"
		case "transfer":
			stop["stopType"] = "handoff"
		}
		out = append(out, stop)
	}
	return out
}

func journeyDTO(j bson.M) bson.M {
	keys := []string{"journeyId", "parentJourneyId", "planVersion", "routeMode", "status", "estimatedDeliveryAt", "totalCostUnits", "capacityUsed", "capacityAvailable", "sampleIds", "orderedStops", "legs", "assignedWorkerIds", "collectionAssignmentId", "collectionAssignmentIds", "nodeAssignmentIds", "laboratoryAssignmentIds", "firstTransportAssignmentId", "middleTransportAssignmentId", "finalTransportAssignmentId", "valid", "replanStatus", "splitJourney", "replacementJourney"}
	out := bson.M{}
	for _, k := range keys {
		if v, ok := j[k]; ok && v != nil {
			switch k {
			case "orderedStops":
				out[k] = journeyStops(v)
			case "splitJourney", "replacementJourney":
				out[k] = journeyDTO(toBson(v))
			default:
				out[k] = v
			}
		}
	}
	return out
}

func (a *App) handleReadJourney(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	var j bson.M
	if a.db.Collection("journeys").FindOne(r.Context(), bson.M{"journeyId": asString(body["journeyId"])}).Decode(&j) != nil {
		return nil, 0, fail(404, "not_found", "Journey not found")
	}
	if actor.ActiveRole == "administrator" || actor.ActiveRole == "dispatcher" {
		return journeyDTO(j), 200, nil
	}
	samples := stringSlice(j["sampleIds"])
	if actor.ActiveRole == "requester" {
		allowed := false
		for _, id := range samples {
			var s bson.M
			if a.db.Collection("samples").FindOne(r.Context(), bson.M{"sampleId": id, "requesterId": actor.UserID}).Decode(&s) == nil {
				allowed = true
			}
		}
		if !allowed {
			return nil, 0, fail(403, "forbidden", "Journey belongs to another requester")
		}
		out := bson.M{"journeyId": asString(j["journeyId"]), "sampleIds": orArray(j["sampleIds"]), "legs": orArray(j["legs"])}
		for _, k := range []string{"parentJourneyId", "planVersion", "routeMode", "status", "estimatedDeliveryAt", "totalCostUnits"} {
			if v, ok := j[k]; ok {
				out[k] = v
			}
		}
		out["orderedStops"] = journeyStops(j["orderedStops"])
		return out, 200, nil
	}
	assignments := a.findAll(r.Context(), "assignments", bson.M{"journeyId": j["journeyId"], "workerId": actor.UserID, "requiredRole": actor.ActiveRole})
	if len(assignments) == 0 {
		return nil, 0, fail(403, "forbidden", "Journey is outside selected-role scope")
	}
	ids := bson.A{}
	legs := bson.A{}
	for _, x := range assignments {
		ids = append(ids, x["assignmentId"])
		if asString(x["kind"]) == "transport" {
			legs = append(legs, bson.M{"assignmentId": x["assignmentId"], "sequence": asInt(x["sequence"]), "status": asString(x["status"]), "fromLocationId": asString(x["fromLocationId"]), "toLocationId": asString(x["toLocationId"]), "workerId": actor.UserID, "sampleId": asString(x["sampleId"])})
		}
	}
	return bson.M{"journeyId": j["journeyId"], "planVersion": asInt(j["planVersion"]), "routeMode": j["routeMode"], "status": j["status"], "scope": "assigned_legs", "assignmentIds": ids, "legs": legs, "orderedStops": journeyStops(j["orderedStops"])}, 200, nil
}

func (a *App) handleRoleWork(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	role := asString(body["role"])
	if role == "" {
		role = actor.ActiveRole
	}
	if role != actor.ActiveRole {
		return nil, 0, fail(403, "forbidden", "Work views use the selected role")
	}
	pending, inProgress, completed := bson.A{}, bson.A{}, bson.A{}
	put := func(status string, item bson.M) {
		switch status {
		case "received", "completed", "cancelled", "delivered":
			completed = append(completed, item)
		case "accepted", "in_progress", "in_transit", "picked_up", "arrived", "sealed", "exception":
			inProgress = append(inProgress, item)
		default:
			pending = append(pending, item)
		}
	}
	if role == "requester" {
		for _, s := range a.findAll(r.Context(), "samples", bson.M{"requesterId": actor.UserID}) {
			item := bson.M{"kind": "sample", "sampleId": s["sampleId"], "requestId": s["requestId"], "status": s["status"], "serviceability": s["serviceability"], "requestedAt": s["requestedAt"], "deliveryDeadline": s["deliveryDeadline"], "earliestCollectionAt": s["earliestCollectionAt"], "latestCollectionAt": s["latestCollectionAt"], "history": orArray(s["timeline"]), "locationStale": stale(s["locationRecordedAt"])}
			for _, k := range []string{"activeJourneyId", "currentHolderId", "locationRecordedAt"} {
				if v := asString(s[k]); v != "" {
					item[k] = v
				}
			}
			if v := asString(s["targetLaboratoryId"]); v != "" {
				item["laboratoryId"] = v
			}
			put(asString(s["status"]), item)
		}
	} else if role == "administrator" || role == "dispatcher" {
		for _, j := range a.findAll(r.Context(), "journeys", bson.M{}) {
			history := bson.A{}
			for _, sid := range stringSlice(j["sampleIds"]) {
				var s bson.M
				_ = a.db.Collection("samples").FindOne(r.Context(), bson.M{"sampleId": sid}).Decode(&s)
				if ts, ok := s["timeline"].(bson.A); ok {
					history = append(history, ts...)
				}
			}
			count, _ := a.db.Collection("assignments").CountDocuments(r.Context(), bson.M{"journeyId": j["journeyId"]})
			item := bson.M{"kind": "journey", "journeyId": j["journeyId"], "status": j["status"], "routeMode": j["routeMode"], "planVersion": asInt(j["planVersion"]), "sampleIds": orArray(j["sampleIds"]), "estimatedDeliveryAt": asString(j["estimatedDeliveryAt"]), "assignmentCount": int(count), "history": history}
			put(asString(j["status"]), item)
		}
	} else {
		filter := bson.M{"workerId": actor.UserID, "requiredRole": role}
		for _, x := range a.findAll(r.Context(), "assignments", filter) {
			item := bson.M{"kind": x["kind"], "assignmentId": x["assignmentId"], "sampleId": x["sampleId"], "status": x["status"], "history": orArray(x["history"])}
			for _, k := range []string{"journeyId", "fromLocationId", "toLocationId", "nodeId", "laboratoryId", "offerExpiresAt"} {
				if v := asString(x[k]); v != "" {
					item[k] = v
				}
			}
			item["sequence"] = asInt(x["sequence"])
			if asString(x["kind"]) == "laboratory" {
				item["laboratoryId"] = asString(x["nodeId"])
			}
			put(asString(x["status"]), item)
		}
	}
	if wanted := asString(body["status"]); wanted != "" {
		switch wanted {
		case "pending":
			inProgress = bson.A{}
			completed = bson.A{}
		case "in_progress":
			pending = bson.A{}
			completed = bson.A{}
		case "completed":
			pending = bson.A{}
			inProgress = bson.A{}
		}
	}
	return bson.M{"pending": pending, "inProgress": inProgress, "completed": completed}, 200, nil
}

func operationsLocation(l bson.M) bson.M {
	out := bson.M{"id": asString(l["locationId"]), "locationId": asString(l["locationId"]), "name": asString(l["name"]), "coordinate": coordinate(l["coordinate"]), "active": asBool(l["active"]), "coverageKm": asFloat(l["coverageKm"]), "handlingMinutes": asInt(l["handlingMinutes"]), "functions": coordinate(l["functions"]), "capacity": capacityOf(l)}
	return out
}
func operationsConnection(c bson.M) bson.M {
	return bson.M{"id": asString(c["connectionId"]), "connectionId": asString(c["connectionId"]), "fromLocationId": asString(c["fromLocationId"]), "toLocationId": asString(c["toLocationId"]), "travelMinutes": asInt(c["travelMinutes"]), "costUnits": asFloat(c["costUnits"]), "cooled": asBool(c["cooled"]), "active": asBool(c["active"]), "capacity": capacityOf(c)}
}
func (a *App) operationsDTO(ctx context.Context, locationOnly string) bson.M {
	samples := bson.A{}
	for _, s := range a.findAll(ctx, "samples", bson.M{}) {
		x := bson.M{"sampleId": asString(s["sampleId"]), "status": asString(s["status"]), "locationStale": stale(s["locationRecordedAt"])}
		for _, k := range []string{"requestId", "currentHolderId", "activeJourneyId", "deliveryDeadline", "locationRecordedAt"} {
			if v := asString(s[k]); v != "" {
				x[k] = v
			}
		}
		if c := coordinate(s["origin"]); len(c) > 0 {
			x["origin"] = c
		}
		if c := coordinate(s["latestLocation"]); len(c) > 0 {
			x["latestLocation"] = c
		}
		samples = append(samples, x)
	}
	workers := bson.A{}
	counts := []int{}
	for _, u := range a.findAll(ctx, "users", bson.M{"roles": bson.M{"$in": bson.A{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"}}}) {
		count := asInt(u["assignmentCount"])
		counts = append(counts, count)
		x := bson.M{"workerId": asString(u["userId"]), "fullName": asString(u["fullName"]), "roles": stringSlice(u["roles"]), "available": asBool(u["available"]), "status": map[bool]string{true: "available", false: "unavailable"}[asBool(u["available"])], "capacityUnits": asInt(u["capacityUnits"]), "assignmentCount": count, "locationStale": stale(u["locationRecordedAt"])}
		if c := coordinate(u["latestLocation"]); len(c) > 0 {
			x["latestLocation"] = c
		}
		if t := asString(u["locationRecordedAt"]); t != "" {
			x["locationRecordedAt"] = t
		}
		workers = append(workers, x)
	}
	locations := bson.A{}
	lf := bson.M{}
	if locationOnly != "" {
		lf["locationId"] = locationOnly
	}
	for _, l := range a.findAll(ctx, "locations", lf) {
		x := operationsLocation(l)
		acc := a.findAll(ctx, "capacities", bson.M{"kind": "laboratory_acceptance", "resourceId": l["locationId"], "accepts": true})
		ids := bson.A{}
		for _, v := range acc {
			ids = append(ids, v["sampleTypeId"])
		}
		if len(ids) > 0 {
			x["acceptedSampleTypeIds"] = ids
		}
		locations = append(locations, x)
	}
	connections := bson.A{}
	if locationOnly == "" {
		for _, c := range a.findAll(ctx, "connections", bson.M{}) {
			connections = append(connections, operationsConnection(c))
		}
	}
	routes := bson.A{}
	for _, j := range a.findAll(ctx, "journeys", bson.M{}) {
		routes = append(routes, journeyDTO(j))
	}
	handoffs := bson.A{}
	for _, h := range a.findAll(ctx, "handoffs", bson.M{"status": "pending"}) {
		delete(h, "_id")
		handoffs = append(handoffs, h)
	}
	exceptions := bson.A{}
	for _, x := range a.findAll(ctx, "exceptions", bson.M{}) {
		delete(x, "_id")
		exceptions = append(exceptions, x)
	}
	spread := 0
	if len(counts) > 0 {
		sort.Ints(counts)
		spread = counts[len(counts)-1] - counts[0]
	}
	unassigned, _ := a.db.Collection("assignments").CountDocuments(ctx, bson.M{"status": "unassigned"})
	return bson.M{"samples": samples, "workers": workers, "locations": locations, "connections": connections, "routes": routes, "handoffs": handoffs, "delays": bson.A{}, "exceptions": exceptions, "assignmentCountSpread": spread, "ineligibleAssignmentCount": int(unassigned)}
}

func (a *App) handleOperations(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	return a.operationsDTO(r.Context(), ""), 200, nil
}

func (a *App) handleBootstrapHTTP(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" {
		writeError(w, fail(405, "method_not_allowed", "Method not allowed"))
		return
	}
	actor, e := a.authenticate(r)
	if e != nil {
		writeError(w, e)
		return
	}
	var u bson.M
	if a.db.Collection("users").FindOne(r.Context(), bson.M{"userId": actor.UserID}).Decode(&u) != nil {
		writeError(w, fail(404, "not_found", "User not found"))
		return
	}
	data := bson.M{"user": bson.M{"userId": actor.UserID, "username": actor.Username, "fullName": asString(u["fullName"]), "roles": actor.Roles, "activeRole": actor.ActiveRole, "roleSelectionRequired": actor.ActiveRole == ""}, "serverTime": now()}
	if actor.ActiveRole == "requester" {
		items := bson.A{}
		for _, s := range a.findAll(r.Context(), "samples", bson.M{"requesterId": actor.UserID}) {
			items = append(items, sampleStateDTO(s))
		}
		data["requesterSamples"] = items
	}
	if actor.ActiveRole == "administrator" || actor.ActiveRole == "dispatcher" {
		data["operations"] = a.operationsDTO(r.Context(), "")
	} else if (actor.ActiveRole == "node_handler" || actor.ActiveRole == "laboratory_team") && actor.AssignedLocationID != "" {
		data["operations"] = a.operationsDTO(r.Context(), actor.AssignedLocationID)
	}
	writeJSON(w, 200, bson.M{"data": data})
}

func (a *App) handleReadUserHTTP(w http.ResponseWriter, r *http.Request, id string) {
	if r.Method != "GET" {
		writeError(w, fail(405, "method_not_allowed", "Method not allowed"))
		return
	}
	actor, e := a.authenticate(r)
	if e != nil {
		writeError(w, e)
		return
	}
	if actor.ActiveRole != "administrator" {
		writeError(w, fail(403, "forbidden", "Only administrators can read users"))
		return
	}
	var u bson.M
	if a.db.Collection("users").FindOne(r.Context(), bson.M{"userId": id}).Decode(&u) != nil {
		writeError(w, fail(404, "not_found", "User not found"))
		return
	}
	writeJSON(w, 200, bson.M{"data": publicUser(u)})
}

func (a *App) handleSnapshot(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	regions := bson.A{}
	for _, l := range a.findAll(r.Context(), "locations", bson.M{"active": true, "functions.collection_point": true}) {
		c := coordinate(l["coordinate"])
		regions = append(regions, bson.M{"locationId": l["locationId"], "name": l["name"], "latitude": asFloat(c["latitude"]), "longitude": asFloat(c["longitude"]), "coverageKm": asFloat(l["coverageKm"])})
	}
	var m bson.M
	_ = a.db.Collection("metadata").FindOne(r.Context(), bson.M{"key": "network"}).Decode(&m)
	computed := asString(m["computedAt"])
	if computed == "" {
		computed = now()
	}
	return bson.M{"version": a.networkVersion(r.Context()), "status": "complete", "computedAt": computed, "networkRevision": a.networkVersion(r.Context()), "regions": regions, "activeCollectionPointCount": len(regions)}, 200, nil
}

func (a *App) handleAuditSearch(_ http.ResponseWriter, r *http.Request, actor *Actor, body bsonMap) (any, int, *apiError) {
	filter := bson.M{}
	for _, k := range []string{"actorId", "entityType", "entityId", "action", "role", "success"} {
		if v, ok := body[k]; ok && v != "" {
			filter[k] = v
		}
	}
	if q := asString(body["query"]); q != "" {
		filter["$or"] = bson.A{bson.M{"action": bson.M{"$regex": q, "$options": "i"}}, bson.M{"entityId": bson.M{"$regex": q, "$options": "i"}}, bson.M{"entityType": bson.M{"$regex": q, "$options": "i"}}}
	}
	timeFilter := bson.M{}
	if v := asString(body["fromTime"]); v != "" {
		timeFilter["$gte"] = v
	}
	if v := asString(body["toTime"]); v != "" {
		timeFilter["$lte"] = v
	}
	if len(timeFilter) > 0 {
		filter["occurredAt"] = timeFilter
	}
	limit := asInt(body["limit"])
	if limit <= 0 {
		limit = 50
	}
	if limit > 200 {
		limit = 200
	}
	offset := asInt(body["offset"])
	order := asString(body["order"])
	if order == "" {
		order = "newest_first"
	}
	direction := -1
	if order == "oldest_first" {
		direction = 1
	}
	total, _ := a.db.Collection("audits").CountDocuments(r.Context(), filter)
	cur, e := a.db.Collection("audits").Find(r.Context(), filter, options.Find().SetSort(bson.D{{Key: "occurredAt", Value: direction}}).SetSkip(int64(offset)).SetLimit(int64(limit)))
	if e != nil {
		return nil, 0, fail(500, "internal_error", "Could not search audit trail")
	}
	var docs []bson.M
	_ = cur.All(r.Context(), &docs)
	entries := bson.A{}
	for _, x := range docs {
		entries = append(entries, bson.M{"auditId": asString(x["auditId"]), "actorId": asString(x["actorId"]), "role": asString(x["role"]), "actorRole": asString(x["actorRole"]), "action": asString(x["action"]), "entityType": asString(x["entityType"]), "entityId": asString(x["entityId"]), "success": asBool(x["success"]), "occurredAt": asString(x["occurredAt"]), "details": x["details"]})
	}
	out := bson.M{"entries": entries, "total": int(total), "returned": len(entries), "offset": offset, "limit": limit, "order": order, "hasMore": offset+len(entries) < int(total)}
	if offset+len(entries) < int(total) {
		out["nextOffset"] = offset + len(entries)
	}
	return out, 200, nil
}

func (a *App) handleEvents(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" {
		writeError(w, fail(405, "method_not_allowed", "Method not allowed"))
		return
	}
	actor, e := a.authenticate(r)
	if e != nil {
		writeError(w, e)
		return
	}
	if e = a.authorize(actor, "stream_realtime_events"); e != nil {
		writeError(w, e)
		return
	}
	since, _ := strconv.ParseInt(r.URL.Query().Get("since"), 10, 64)
	filter := bson.M{"sequence": bson.M{"$gt": since}}
	if actor.ActiveRole != "administrator" && actor.ActiveRole != "dispatcher" {
		filter["$or"] = bson.A{bson.M{"audienceRole": actor.ActiveRole}, bson.M{"audienceUserId": actor.UserID}}
	}
	docs := a.findAll(r.Context(), "events", filter)
	sort.Slice(docs, func(i, j int) bool { return asInt(docs[i]["sequence"]) < asInt(docs[j]["sequence"]) })
	events := bson.A{}
	cursor := since
	for _, x := range docs {
		n := int64(asInt(x["sequence"]))
		if n > cursor {
			cursor = n
		}
		events = append(events, bson.M{"id": asString(x["id"]), "type": asString(x["type"]), "entityType": asString(x["entityType"]), "entityId": asString(x["entityId"]), "payload": x["payload"], "createdAt": asString(x["createdAt"])})
	}
	writeJSON(w, 200, bson.M{"data": bson.M{"events": events, "cursor": cursor}})
}

